-- ============================================================================
-- 0027_bestiary_monster_tokens_part1of3.sql
--
-- Full SRD 5.1 bestiary (~327 monsters, CC-BY-4.0) as 'monster' tokens with
-- full statblocks + first-letter monogram placeholder art. Run all 3 parts,
-- in any order. Idempotent: skips a monster you already have by the same name.
-- Attribution: D&D 5.1 SRD, CC-BY-4.0 (see details.source).
-- ============================================================================

do $$
declare
  me uuid;
begin
  select id into me from auth.users where email = 'vinces.gerardo@gmail.com';
  if me is null then raise exception 'No auth user for that email.'; end if;

  insert into public.token_assets (owner_id, name, image_url, token_type, size_category, creature_type, details)
  select me, v.name, v.image_url, 'monster', v.size, v.ctype,
         jsonb_build_object('kind','monster','monster', v.mb::jsonb)
  from (values
    ('Aboleth', '/icons/monsters/_mono/A.svg', 'large', 'aberration', '{"name":"Aboleth","size":"large","type":"aberration","ac":17,"hp":135,"speed":{"walk":10,"swim":40},"abilities":{"str":21,"dex":9,"con":15,"int":18,"wis":15,"cha":18},"cr":"10","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"18d10 + 36","saves":{"con":6,"int":8,"wis":6},"skills":[{"name":"History","bonus":12},{"name":"Perception","bonus":10}],"senses":["Darkvision 120 ft.","Passive Perception 20"],"languages":["Deep Speech","Telepathy 120 ft."],"traits":[{"name":"Amphibious","text":"The aboleth can breathe air and water."},{"name":"Mucous Cloud","text":"While underwater, the aboleth is surrounded by transformative mucus. A creature that touches the aboleth or that hits it with a melee attack while within 5 feet of it must make a DC 14 Constitution saving throw. On a failure, the creature is diseased for 1d4 hours. The diseased creature can breathe only underwater."},{"name":"Probing Telepathy","text":"If a creature communicates telepathically with the aboleth, the aboleth learns the creature''s greatest desires if the aboleth can see the creature."}],"actions":[{"name":"Multiattack","text":"The aboleth makes three tentacle attacks."},{"name":"Tentacle","text":"Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 12 (2d6 + 5) bludgeoning damage. If the target is a creature, it must succeed on a DC 14 Constitution saving throw or become diseased. The disease has no effect for 1 minute and can be removed by any magic that cures disease. After 1 minute, the diseased creature''s skin becomes translucent and slimy, the creature can''t regain hit points unless it is underwater, and the disease can be removed only by heal or another disease-curing spell of 6th level or higher. When the creature is outside a body of water, it takes 6 (1d12) acid damage every 10 minutes unless moisture is applied to the skin before 10 minutes have passed.","attackBonus":9,"reach":"10 ft","damage":"2d6+5","damageType":"bludgeoning","saveDc":14,"saveAbility":"con"},{"name":"Tail","text":"Melee Weapon Attack: +9 to hit, reach 10 ft. one target. Hit: 15 (3d6 + 5) bludgeoning damage.","attackBonus":9,"reach":"10 ft","damage":"3d6+5","damageType":"bludgeoning"},{"name":"Enslave (3/Day)","text":"The aboleth targets one creature it can see within 30 feet of it. The target must succeed on a DC 14 Wisdom saving throw or be magically charmed by the aboleth until the aboleth dies or until it is on a different plane of existence from the target. The charmed target is under the aboleth''s control and can''t take reactions, and the aboleth and the target can communicate telepathically with each other over any distance.","saveDc":14,"saveAbility":"wis"}],"legendaryActions":[{"name":"Detect","text":"The aboleth makes a Wisdom (Perception) check."},{"name":"Tail Swipe","text":"The aboleth makes one tail attack."},{"name":"Psychic Drain","text":"(Costs 2 Actions). One creature charmed by the aboleth takes 10 (3d6) psychic damage, and the aboleth regains hit points equal to the damage the creature takes."}],"legendaryCount":3}'),
    ('Acolyte', '/icons/monsters/_mono/A.svg', 'medium', 'humanoid', '{"name":"Acolyte","size":"medium","type":"humanoid","ac":10,"hp":9,"speed":{"walk":30},"abilities":{"str":10,"dex":10,"con":10,"int":10,"wis":14,"cha":11},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","hitDice":"2d8","skills":[{"name":"Medicine","bonus":4},{"name":"Religion","bonus":2}],"senses":["Passive Perception 12"],"languages":["Any one language (usually Common)"],"traits":[{"name":"Spellcasting","text":"The acolyte is a 1st-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 12, +4 to hit with spell attacks). The acolyte has following cleric spells prepared:"}],"actions":[{"name":"Club","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage.","attackBonus":2,"reach":"5 ft","damage":"1d4","damageType":"bludgeoning"}]}'),
    ('Adult Black Dragon', '/icons/monsters/_mono/A.svg', 'huge', 'dragon', '{"name":"Adult Black Dragon","size":"huge","type":"dragon","ac":19,"hp":195,"speed":{"walk":40,"fly":80,"swim":40},"abilities":{"str":23,"dex":14,"con":21,"int":14,"wis":13,"cha":17},"cr":"14","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"17d12 + 85","saves":{"dex":7,"con":10,"wis":6,"cha":8},"skills":[{"name":"Perception","bonus":11},{"name":"Stealth","bonus":7}],"damageImmunities":["Acid"],"senses":["Blindsight 60 ft.","Darkvision 120 ft.","Passive Perception 21"],"languages":["Common","Draconic"],"traits":[{"name":"Amphibious","text":"The dragon can breathe air and water."},{"name":"Legendary Resistance (3/Day)","text":"If the dragon fails a saving throw, it can choose to succeed instead."}],"actions":[{"name":"Multiattack","text":"The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +11 to hit, reach 10 ft., one target. Hit: 17 (2d10 + 6) piercing damage plus 4 (1d8) acid damage.","attackBonus":11,"reach":"10 ft","damage":"2d10+6","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +11 to hit, reach 5 ft., one target. Hit: 13 (2d6 + 6) slashing damage.","attackBonus":11,"reach":"5 ft","damage":"2d6+6","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +11 to hit, reach 15 ft., one target. Hit: 15 (2d8 + 6) bludgeoning damage.","attackBonus":11,"reach":"15 ft","damage":"2d8+6","damageType":"bludgeoning"},{"name":"Frightful Presence","text":"Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a DC 16 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours.","saveDc":16,"saveAbility":"wis"},{"name":"Acid Breath (Recharge 5–6)","text":"The dragon exhales acid in a 60-­foot line that is 5 feet wide. Each creature in that line must make a DC 18 Dexterity saving throw, taking 54 (12d8) acid damage on a failed save, or half as much damage on a successful one.","saveDc":18,"saveAbility":"dex"}],"legendaryActions":[{"name":"Detect","text":"The dragon makes a Wisdom (Perception) check."},{"name":"Tail Attack","text":"The dragon makes a tail attack."},{"name":"Wing Attack (Costs 2 Actions)","text":"The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a DC 19 Dexterity saving throw or take 13 (2d6 + 6) bludgeoning damage and be knocked prone. The dragon can then fly up to half its flying speed."}],"legendaryCount":3}'),
    ('Adult Blue Dragon', '/icons/monsters/_mono/A.svg', 'huge', 'dragon', '{"name":"Adult Blue Dragon","size":"huge","type":"dragon","ac":19,"hp":225,"speed":{"walk":40,"burrow":30,"fly":80},"abilities":{"str":25,"dex":10,"con":23,"int":16,"wis":15,"cha":19},"cr":"16","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"18d12 + 108","saves":{"dex":5,"con":11,"wis":7,"cha":9},"skills":[{"name":"Perception","bonus":12},{"name":"Stealth","bonus":5}],"damageImmunities":["Lightning"],"senses":["Blindsight 60 ft.","Darkvision 120 ft.","Passive Perception 22"],"languages":["Common","Draconic"],"traits":[{"name":"Legendary Resistance (3/Day)","text":"If the dragon fails a saving throw, it can choose to succeed instead."}],"actions":[{"name":"Multiattack","text":"The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +12 to hit, reach 10 ft., one target. Hit: 18 (2d10 + 7) piercing damage plus 5 (1d10) lightning damage.","attackBonus":12,"reach":"10 ft","damage":"2d10+7","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +12 to hit, reach 5 ft., one target. Hit: 14 (2d6 + 7) slashing damage.","attackBonus":12,"reach":"5 ft","damage":"2d6+7","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +12 to hit, reach 15 ft., one target. Hit: 16 (2d8 + 7) bludgeoning damage.","attackBonus":12,"reach":"15 ft","damage":"2d8+7","damageType":"bludgeoning"},{"name":"Frightful Presence","text":"Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a DC 17 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours.","saveDc":17,"saveAbility":"wis"},{"name":"Lightning Breath (Recharge 5–6)","text":"The dragon exhales lightning in a 90-­foot line that is 5 feet wide. Each creature in that line must make a DC 19 Dexterity saving throw, taking 66 (12d10) lightning damage on a failed save, or half as much damage on a successful one.","saveDc":19,"saveAbility":"dex"}],"legendaryActions":[{"name":"Detect","text":"The dragon makes a Wisdom (Perception) check."},{"name":"Tail Attack","text":"The dragon makes a tail attack."},{"name":"Wing Attack (Costs 2 Actions)","text":"The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a DC 20 Dexterity saving throw or take 14 (2d6 + 7) bludgeoning damage and be knocked prone. The dragon can then fly up to half its flying speed."}],"legendaryCount":3}'),
    ('Adult Brass Dragon', '/icons/monsters/_mono/A.svg', 'huge', 'dragon', '{"name":"Adult Brass Dragon","size":"huge","type":"dragon","ac":18,"hp":172,"speed":{"walk":40,"burrow":30,"fly":80},"abilities":{"str":23,"dex":10,"con":21,"int":14,"wis":13,"cha":17},"cr":"13","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","acNote":"Natural Armor","hitDice":"15d12 + 75","saves":{"dex":5,"con":10,"wis":6,"cha":8},"skills":[{"name":"History","bonus":7},{"name":"Perception","bonus":11},{"name":"Persuasion","bonus":8},{"name":"Stealth","bonus":5}],"damageImmunities":["Fire"],"senses":["Blindsight 60 ft.","Darkvision 120 ft.","Passive Perception 21"],"languages":["Common","Draconic"],"traits":[{"name":"Legendary Resistance (3/Day)","text":"If the dragon fails a saving throw, it can choose to succeed instead."}],"actions":[{"name":"Multiattack","text":"The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +11 to hit, reach 10 ft., one target. Hit: 17 (2d10 + 6) piercing damage.","attackBonus":11,"reach":"10 ft","damage":"2d10+6","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +11 to hit, reach 5 ft., one target. Hit: 13 (2d6 + 6) slashing damage.","attackBonus":11,"reach":"5 ft","damage":"2d6+6","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +11 to hit, reach 15 ft., one target. Hit: 15 (2d8 + 6) bludgeoning damage.","attackBonus":11,"reach":"15 ft","damage":"2d8+6","damageType":"bludgeoning"},{"name":"Frightful Presence","text":"Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a DC 16 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours.","saveDc":16,"saveAbility":"wis"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Fire Breath","text":"The dragon exhales fire in an 60-foot line that is 5 feet wide. Each creature in that line must make a DC 18 Dexterity saving throw, taking 45 (13d6) fire damage on a failed save, or half as much damage on a successful one.","saveDc":18,"saveAbility":"dex"},{"name":"Sleep Breath","text":"The dragon exhales sleep gas in a 60-foot cone. Each creature in that area must succeed on a DC 18 Constitution saving throw or fall unconscious for 10 minutes. This effect ends for a creature if the creature takes damage or someone uses an action to wake it.","saveDc":18,"saveAbility":"con"}],"legendaryActions":[{"name":"Detect","text":"The dragon makes a Wisdom (Perception) check."},{"name":"Tail Attack","text":"The dragon makes a tail attack."},{"name":"Wing Attack (Costs 2 Actions)","text":"The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a DC 19 Dexterity saving throw or take 13 (2d6 + 6) bludgeoning damage and be knocked prone. The dragon can then fly up to half its flying speed."}],"legendaryCount":3}'),
    ('Adult Bronze Dragon', '/icons/monsters/_mono/A.svg', 'huge', 'dragon', '{"name":"Adult Bronze Dragon","size":"huge","type":"dragon","ac":19,"hp":212,"speed":{"walk":40,"fly":80,"swim":40},"abilities":{"str":25,"dex":10,"con":23,"int":16,"wis":15,"cha":19},"cr":"15","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"17d12 + 102","saves":{"dex":5,"con":11,"wis":7,"cha":9},"skills":[{"name":"Insight","bonus":7},{"name":"Perception","bonus":12},{"name":"Stealth","bonus":5}],"damageImmunities":["Lightning"],"senses":["Blindsight 60 ft.","Darkvision 120 ft.","Passive Perception 22"],"languages":["Common","Draconic"],"traits":[{"name":"Amphibious","text":"The dragon can breathe air and water."},{"name":"Legendary Resistance (3/Day)","text":"If the dragon fails a saving throw, it can choose to succeed instead."}],"actions":[{"name":"Multiattack","text":"The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +12 to hit, reach 10 ft., one target. Hit: 18 (2d10 + 7) piercing damage.","attackBonus":12,"reach":"10 ft","damage":"2d10+7","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +12 to hit, reach 5 ft., one target. Hit: 14 (2d6 + 7) slashing damage.","attackBonus":12,"reach":"5 ft","damage":"2d6+7","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +12 to hit, reach 15 ft., one target. Hit: 16 (2d8 + 7) bludgeoning damage.","attackBonus":12,"reach":"15 ft","damage":"2d8+7","damageType":"bludgeoning"},{"name":"Frightful Presence","text":"Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a DC 17 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the 