    ('Adult Copper Dragon', '/icons/monsters/_mono/A.svg', 'huge', 'dragon', '{"name":"Adult Copper Dragon","size":"huge","type":"dragon","ac":18,"hp":184,"speed":{"walk":40,"climb":40,"fly":80},"abilities":{"str":23,"dex":12,"con":21,"int":18,"wis":15,"cha":17},"cr":"14","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","acNote":"Natural Armor","hitDice":"16d12 + 80","saves":{"dex":6,"con":10,"wis":7,"cha":8},"skills":[{"name":"Deception","bonus":8},{"name":"Perception","bonus":12},{"name":"Stealth","bonus":6}],"damageImmunities":["Acid"],"senses":["Blindsight 60 ft.","Darkvision 120 ft.","Passive Perception 22"],"languages":["Common","Draconic"],"traits":[{"name":"Legendary Resistance (3/Day)","text":"If the dragon fails a saving throw, it can choose to succeed instead."}],"actions":[{"name":"Multiattack","text":"The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +11 to hit, reach 10 ft., one target. Hit: 17 (2d10 + 6) piercing damage.","attackBonus":11,"reach":"10 ft","damage":"2d10+6","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +11 to hit, reach 5 ft., one target. Hit: 13 (2d6 + 6) slashing damage.","attackBonus":11,"reach":"5 ft","damage":"2d6+6","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +11 to hit, reach 15 ft., one target. Hit: 15 (2d8 + 6) bludgeoning damage.","attackBonus":11,"reach":"15 ft","damage":"2d8+6","damageType":"bludgeoning"},{"name":"Frightful Presence","text":"Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a DC 16 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours.","saveDc":16,"saveAbility":"wis"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Acid Breath","text":"The dragon exhales acid in an 60-foot line that is 5 feet wide. Each creature in that line must make a DC 18 Dexterity saving throw, taking 54 (12d8) acid damage on a failed save, or half as much damage on a successful one.","saveDc":18,"saveAbility":"dex"},{"name":"Slowing Breath","text":"The dragon exhales gas in a 60-foot cone. Each creature in that area must succeed on a DC 18 Constitution saving throw. On a failed save, the creature can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the creature can use either an action or a bonus action on its turn, but not both. These effects last for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself with a successful save.","saveDc":18,"saveAbility":"con"}],"legendaryActions":[{"name":"Detect","text":"The dragon makes a Wisdom (Perception) check."},{"name":"Tail Attack","text":"The dragon makes a tail attack."},{"name":"Wing Attack (Costs 2 Actions)","text":"The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a DC 19 Dexterity saving throw or take 13 (2d6 + 6) bludgeoning damage and be knocked prone. The dragon can then fly up to half its flying speed."}],"legendaryCount":3}'),
