    ('Air Elemental', '/icons/monsters/_mono/A.svg', 'large', 'elemental', '{"name":"Air Elemental","size":"large","type":"elemental","ac":15,"hp":90,"speed":{"walk":0,"fly":90,"hover":true},"abilities":{"str":14,"dex":20,"con":14,"int":6,"wis":10,"cha":6},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"12d10 + 24","damageResistances":["Lightning","Thunder","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"conditionImmunities":["Exhaustion","Grappled","Paralyzed","Petrified","Poisoned","Prone","Restrained","Unconscious"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Auran"],"traits":[{"name":"Air Form","text":"The elemental can enter a hostile creature''s space and stop there. It can move through a space as narrow as 1 inch wide without squeezing."}],"actions":[{"name":"Multiattack","text":"The elemental makes two slam attacks."},{"name":"Slam","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 14 (2d8 + 5) bludgeoning damage.","attackBonus":8,"reach":"5 ft","damage":"2d8+5","damageType":"bludgeoning"},{"name":"Whirlwind (Recharge 4–6)","text":"Each creature in the elemental''s space must make a DC 13 Strength saving throw. On a failure, a target takes 15 (3d8 + 2) bludgeoning damage and is flung up 20 feet away from the elemental in a random direction and knocked prone. If a thrown target strikes an object, such as a wall or floor, the target takes 3 (1d6) bludgeoning damage for every 10 feet it was thrown. If the target is thrown at another creature, that creature must succeed on a DC 13 Dexterity saving throw or take the same damage and be knocked prone.","saveDc":13,"saveAbility":"str"}]}'),
