    ('Ancient Bronze Dragon', '/icons/monsters/_mono/A.svg', 'gargantuan', 'dragon', '{"name":"Ancient Bronze Dragon","size":"gargantuan","type":"dragon","ac":22,"hp":444,"speed":{"walk":40,"fly":80,"swim":40},"abilities":{"str":29,"dex":10,"con":27,"int":18,"wis":17,"cha":21},"cr":"22","proficiencyBonus":7,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"24d20 + 192","saves":{"dex":7,"con":15,"wis":10,"cha":12},"skills":[{"name":"Insight","bonus":10},{"name":"Perception","bonus":17},{"name":"Stealth","bonus":7}],"damageImmunities":["Lightning"],"senses":["Blindsight 60 ft.","Darkvision 120 ft.","Passive Perception 27"],"languages":["Common","Draconic"],"traits":[{"name":"Amphibious","text":"The dragon can breathe air and water."},{"name":"Legendary Resistance (3/Day)","text":"If the dragon fails a saving throw, it can choose to succeed instead."}],"actions":[{"name":"Multiattack","text":"The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +16 to hit, reach 15 ft., one target. Hit: 20 (2d10 + 9) piercing damage.","attackBonus":16,"reach":"15 ft","damage":"2d10+9","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +16 to hit, reach 10 ft., one target. Hit: 16 (2d6 + 9) slashing damage.","attackBonus":16,"reach":"10 ft","damage":"2d6+9","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +16 to hit, reach 20 ft., one target. Hit: 18 (2d8 + 9) bludgeoning damage.","attackBonus":16,"reach":"20 ft","damage":"2d8+9","damageType":"bludgeoning"},{"name":"Frightful Presence","text":"Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a DC 20 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours.","saveDc":20,"saveAbility":"wis"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Lightning Breath","text":"The dragon exhales lightning in a 120-foot line that is 10 feet wide. Each creature in that line must make a DC 23 Dexterity saving throw, taking 88 (16d10) lightning damage on a failed save, or half as much damage on a successful one.","saveDc":23,"saveAbility":"dex"},{"name":"Repulsion Breath","text":"The dragon exhales repulsion energy in a 30-foot cone. Each creature in that area must succeed on a DC 23 Strength saving throw. On a failed save, the creature is pushed 60 feet away from the dragon.","saveDc":23,"saveAbility":"str"},{"name":"Change Shape","text":"The dragon magically polymorphs into a humanoid or beast that has a challenge rating no higher than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the dragon''s choice)."}],"legendaryActions":[{"name":"Detect","text":"The dragon makes a Wisdom (Perception) check."},{"name":"Tail Attack","text":"The dragon makes a tail attack."},{"name":"Wing Attack (Costs 2 Actions)","text":"The dragon beats its wings. Each creature within 15 feet of the dragon must succeed on a DC 24 Dexterity saving throw or take 16 (2d6 + 9) bludgeoning damage and be knocked prone. The dragon can then fly up to half its flying speed."}],"legendaryCount":3}'),
