    ('Ancient White Dragon', '/icons/monsters/_mono/A.svg', 'gargantuan', 'dragon', '{"name":"Ancient White Dragon","size":"gargantuan","type":"dragon","ac":20,"hp":333,"speed":{"walk":40,"burrow":40,"fly":80,"swim":40},"abilities":{"str":26,"dex":10,"con":26,"int":10,"wis":13,"cha":14},"cr":"20","proficiencyBonus":6,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"18d20 + 144","saves":{"dex":6,"con":14,"wis":7,"cha":8},"skills":[{"name":"Perception","bonus":13},{"name":"Stealth","bonus":6}],"damageImmunities":["Cold"],"senses":["Blindsight 60 ft.","Darkvision 120 ft.","Passive Perception 23"],"languages":["Common","Draconic"],"traits":[{"name":"Ice Walk","text":"The dragon can move across and climb icy surfaces without needing to make an ability check. Additionally, difficult terrain composed of ice or snow doesn''t cost it extra movement."},{"name":"Legendary Resistance (3/Day)","text":"If the dragon fails a saving throw, it can choose to succeed instead."}],"actions":[{"name":"Multiattack","text":"The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +14 to hit, reach 15 ft., one target. Hit: 19 (2d10 + 8) piercing damage plus 9 (2d8) cold damage.","attackBonus":14,"reach":"15 ft","damage":"2d10+8","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 15 (2d6 + 8) slashing damage.","attackBonus":14,"reach":"10 ft","damage":"2d6+8","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +14 to hit, reach 20 ft., one target. Hit: 17 (2d8 + 8) bludgeoning damage.","attackBonus":14,"reach":"20 ft","damage":"2d8+8","damageType":"bludgeoning"},{"name":"Frightful Presence","text":"Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a DC 16 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours.","saveDc":16,"saveAbility":"wis"},{"name":"Cold Breath (Recharge 5–6)","text":"The dragon exhales an icy blast in a 90-foot cone. Each creature in that area must make a DC 22 Constitution saving throw, taking 72 (16d8) cold damage on a failed save, or half as much damage on a successful one.","saveDc":22,"saveAbility":"con"}],"legendaryActions":[{"name":"Detect","text":"The dragon makes a Wisdom (Perception) check."},{"name":"Tail Attack","text":"The dragon makes a tail attack."},{"name":"Wing Attack (Costs 2 Actions)","text":"The dragon beats its wings. Each creature within 15 feet of the dragon must succeed on a DC 22 Dexterity saving throw or take 15 (2d6 + 8) bludgeoning damage and be knocked prone. The dragon can then fly up to half its flying speed."}],"legendaryCount":3}'),
    ('Androsphinx', '/icons/monsters/_mono/A.svg', 'large', 'monstrosity', '{"name":"Androsphinx","size":"large","type":"monstrosity","ac":17,"hp":199,"speed":{"walk":40,"fly":60},"abilities":{"str":22,"dex":10,"con":20,"int":16,"wis":18,"cha":23},"cr":"17","proficiencyBonus":6,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful neutral","acNote":"Natural Armor","hitDice":"19d10 + 95","saves":{"dex":6,"con":11,"int":9,"wis":10},"skills":[{"name":"Arcana","bonus":9},{"name":"Perception","bonus":10},{"name":"Religion","bonus":15}],"damageImmunities":["Psychic","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"conditionImmunities":["Charmed","Frightened"],"senses":["Truesight 120 ft.","Passive Perception 20"],"languages":["Common","Sphinx"],"traits":[{"name":"Inscrutable","text":"The sphinx is immune to any effect that would sense its emotions or read its thoughts, as well as any divination spell that it refuses. Wisdom (Insight) checks made to ascertain the sphinx''s intentions or sincerity have disadvantage."},{"name":"Magic Weapons","text":"The sphinx''s weapon attacks are magical."},{"name":"Spellcasting","text":"The sphinx is a 12th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 18, +10 to hit with spell attacks). It requires no material components to cast its spells. The sphinx has the following cleric spells prepared:"}],"actions":[{"name":"Multiattack","text":"The sphinx makes two claw attacks."},{"name":"Claw","text":"Melee Weapon Attack: +12 to hit, reach 5 ft., one target. Hit: 17 (2d10 + 6) slashing damage.","attackBonus":12,"reach":"5 ft","damage":"2d10+6","damageType":"slashing"},{"name":"Roar (3/Day)","text":"The sphinx emits a magical roar. Each time it roars before finishing a long rest, the roar is louder and the effect is different, as detailed below. Each creature within 500 feet of the sphinx and able to hear the roar must make a saving throw."},{"name":"First Roar","text":"Each creature that fails a DC 18 Wisdom saving throw is frightened for 1 minute. A frightened creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","saveDc":18,"saveAbility":"wis"},{"name":"Second Roar","text":"Each creature that fails a DC 18 Wisdom saving throw is deafened and frightened for 1 minute. A frightened creature is paralyzed and can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","saveDc":18,"saveAbility":"wis"},{"name":"Third Roar","text":"Each creature makes a DC 18 Constitution saving throw. On a failed save, a creature takes 44 (8d10) thunder damage and is knocked prone. On a successful save, the creature takes half as much damage and isn''t knocked prone.","saveDc":18,"saveAbility":"con"}],"legendaryActions":[{"name":"Claw Attack","text":"The sphinx makes one claw attack."},{"name":"Teleport (Costs 2 Actions)","text":"The sphinx magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."},{"name":"Cast a Spell (Costs 3 Actions)","text":"The sphinx casts a spell from its list of prepared spells, using a spell slot as normal."}],"legendaryCount":3}'),
    ('Animated Armor', '/icons/monsters/_mono/A.svg', 'medium', 'construct', '{"name":"Animated Armor","size":"medium","type":"construct","ac":18,"hp":33,"speed":{"walk":25},"abilities":{"str":14,"dex":11,"con":13,"int":1,"wis":3,"cha":1},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"6d8 + 6","damageImmunities":["Poison","Psychic"],"conditionImmunities":["Blinded","Charmed","Deafened","Exhaustion","Frightened","Paralyzed","Petrified","Poisoned"],"senses":["Blindsight 60 ft.","Passive Perception 6"],"languages":["--"],"traits":[{"name":"Antimagic Susceptibility","text":"The armor is incapacitated while in the area of an antimagic field. If targeted by dispel magic, the armor must succeed on a Constitution saving throw against the caster''s spell save DC or fall unconscious for 1 minute."},{"name":"False Appearance","text":"While the armor remains motionless, it is indistinguishable from a normal suit of armor."}],"actions":[{"name":"Multiattack","text":"The armor makes two melee attacks."},{"name":"Slam","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) bludgeoning damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"bludgeoning"}]}'),
    ('Ankheg', '/icons/monsters/_mono/A.svg', 'large', 'monstrosity', '{"name":"Ankheg","size":"large","type":"monstrosity","ac":14,"hp":39,"speed":{"walk":30,"burrow":10},"abilities":{"str":17,"dex":11,"con":13,"int":1,"wis":13,"cha":6},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"6d10 + 6","senses":["Darkvision 60 ft.","Tremorsense 60 ft.","Passive Perception 11"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage plus 3 (1d6) acid damage. If the target is a Large or smaller creature, it is grappled (escape DC 13). Until this grapple ends, the ankheg can bite only the grappled creature and has advantage on attack rolls to do so.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"slashing"},{"name":"Acid Spray (Recharge 6)","text":"The ankheg spits acid in a line that is 30 feet long and 5 feet wide, provided that it has no creature grappled. Each creature in that line must make a DC 13 Dexterity saving throw, taking 10 (3d6) acid damage on a failed save, or half as much damage on a successful one.","saveDc":13,"saveAbility":"dex"}]}'),
    ('Ankylosaurus', '/icons/monsters/_mono/A.svg', 'huge', 'beast', '{"name":"Ankylosaurus","size":"huge","type":"beast","ac":15,"hp":68,"speed":{"walk":30},"abilities":{"str":19,"dex":11,"con":15,"int":2,"wis":12,"cha":5},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"8d12 + 16","senses":["Passive Perception 11"],"languages":["--"],"actions":[{"name":"Tail","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 18 (4d6 + 4) bludgeoning damage. If the target is a creature, it must succeed on a DC 14 Strength saving throw or be knocked prone.","attackBonus":7,"reach":"10 ft","damage":"4d6+4","damageType":"bludgeoning","saveDc":14,"saveAbility":"str"}]}'),
    ('Ape', '/icons/monsters/_mono/A.svg', 'medium', 'beast', '{"name":"Ape","size":"medium","type":"beast","ac":12,"hp":19,"speed":{"walk":30,"climb":30},"abilities":{"str":16,"dex":14,"con":14,"int":6,"wis":12,"cha":7},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d8 + 6","skills":[{"name":"Athletics","bonus":5},{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"actions":[{"name":"Multiattack","text":"The ape makes two fist attacks."},{"name":"Fist","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) bludgeoning damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"bludgeoning"},{"name":"Rock","text":"Ranged Weapon Attack: +5 to hit, range 25/50 ft., one target. Hit: 6 (1d6 + 3) bludgeoning damage.","attackBonus":5,"reach":"range 25/50 ft","damage":"1d6+3","damageType":"bludgeoning"}]}'),
    ('Archmage', '/icons/monsters/_mono/A.svg', 'medium', 'humanoid', '{"name":"Archmage","size":"medium","type":"humanoid","ac":12,"hp":99,"speed":{"walk":30},"abilities":{"str":10,"dex":14,"con":12,"int":20,"wis":15,"cha":16},"cr":"12","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"15 With Mage Armor","hitDice":"18d8 + 18","saves":{"int":9,"wis":6},"skills":[{"name":"Arcana","bonus":13},{"name":"History","bonus":13}],"senses":["Passive Perception 12"],"languages":["Any six languages"],"traits":[{"name":"Magic Resistance","text":"The archmage has advantage on saving throws against spells and other magical effects."},{"name":"Spellcasting","text":"The archmage is an 18th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 17, +9 to hit with spell attacks). The archmage can cast disguise self and invisibility at will and has the following wizard spells prepared:"}],"actions":[{"name":"Dagger","text":"Melee or Ranged Weapon Attack: +6 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"1d4+2","damageType":"piercing"}]}'),
    ('Assassin', '/icons/monsters/_mono/A.svg', 'medium', 'humanoid', '{"name":"Assassin","size":"medium","type":"humanoid","ac":15,"hp":78,"speed":{"walk":30},"abilities":{"str":11,"dex":16,"con":14,"int":13,"wis":11,"cha":10},"cr":"8","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Studded Leather","hitDice":"12d8 + 24","saves":{"dex":6,"int":4},"skills":[{"name":"Acrobatics","bonus":6},{"name":"Deception","bonus":3},{"name":"Perception","bonus":3},{"name":"Stealth","bonus":9}],"damageResistances":["Poison"],"senses":["Passive Perception 13"],"languages":["Thieves'' cant plus any two languages"],"traits":[{"name":"Assassinate","text":"During its first turn, the assassin has advantage on attack rolls against any creature that hasn''t taken a turn. Any hit the assassin scores against a surprised creature is a critical hit."},{"name":"Evasion","text":"If the assassin is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the assassin instead takes no damage if it succeeds on the saving throw, and only half damage if it fails."},{"name":"Sneak Attack","text":"Once per turn, the assassin deals an extra 14 (4d6) damage when it hits a target with a weapon attack and has advantage on the attack roll, or when the target is within 5 feet of an ally of the assassin that isn''t incapacitated and the assassin doesn''t have disadvantage on the attack roll."}],"actions":[{"name":"Multiattack","text":"The assassin makes two shortsword attacks."},{"name":"Shortsword","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage, and the target must make a DC 15 Constitution saving throw, taking 24 (7d6) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":6,"reach":"5 ft","damage":"1d6+3","damageType":"piercing","saveDc":15,"saveAbility":"con"},{"name":"Light Crossbow","text":"Ranged Weapon Attack: +6 to hit, range 80/320 ft., one target. Hit: 7 (1d8 + 3) piercing damage, and the target must make a DC 15 Constitution saving throw, taking 24 (7d6) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":6,"reach":"range 80/320 ft","damage":"1d8+3","damageType":"piercing","saveDc":15,"saveAbility":"con"}]}'),
    ('Awakened Shrub', '/icons/monsters/_mono/A.svg', 'small', 'plant', '{"name":"Awakened Shrub","size":"small","type":"plant","ac":9,"hp":10,"speed":{"walk":20},"abilities":{"str":3,"dex":8,"con":11,"int":10,"wis":10,"cha":6},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d6","damageResistances":["Piercing"],"damageVulnerabilities":["Fire"],"senses":["Passive Perception 10"],"languages":["One language known by its creator"],"traits":[{"name":"False Appearance","text":"While the shrub remains motionless, it is indistinguishable from a normal shrub."}],"actions":[{"name":"Rake","text":"Melee Weapon Attack: +1 to hit, reach 5 ft., one target. Hit: 1 (1d4 − 1) slashing damage.","attackBonus":1,"reach":"5 ft"}]}'),
    ('Awakened Tree', '/icons/monsters/_mono/A.svg', 'huge', 'plant', '{"name":"Awakened Tree","size":"huge","type":"plant","ac":13,"hp":59,"speed":{"walk":20},"abilities":{"str":19,"dex":6,"con":15,"int":10,"wis":10,"cha":7},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"7d12 + 14","damageResistances":["Bludgeoning","Piercing"],"damageVulnerabilities":["Fire"],"senses":["Passive Perception 10"],"languages":["One language known by its creator"],"traits":[{"name":"False Appearance","text":"While the tree remains motionless, it is indistinguishable from a normal tree."}],"actions":[{"name":"Slam","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 14 (3d6 + 4) bludgeoning damage.","attackBonus":6,"reach":"10 ft","damage":"3d6+4","damageType":"bludgeoning"}]}'),
    ('Axe Beak', '/icons/monsters/_mono/A.svg', 'large', 'beast', '{"name":"Axe Beak","size":"large","type":"beast","ac":11,"hp":19,"speed":{"walk":50},"abilities":{"str":14,"dex":12,"con":12,"int":2,"wis":10,"cha":5},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d10 + 3","senses":["Passive Perception 10"],"languages":["--"],"actions":[{"name":"Beak","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"slashing"}]}'),
    ('Azer', '/icons/monsters/_mono/A.svg', 'medium', 'elemental', '{"name":"Azer","size":"medium","type":"elemental","ac":17,"hp":39,"speed":{"walk":30},"abilities":{"str":17,"dex":12,"con":15,"int":12,"wis":13,"cha":10},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful neutral","acNote":"Natural Armor, Shield","hitDice":"6d8 + 12","saves":{"con":4},"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Passive Perception 11"],"languages":["Ignan"],"traits":[{"name":"Heated Body","text":"A creature that touches the azer or hits it with a melee attack while within 5 feet of it takes 5 (1d10) fire damage."},{"name":"Heated Weapons","text":"When the azer hits with a metal melee weapon, it deals an extra 3 (1d6) fire damage (included in the attack)."},{"name":"Illumination","text":"The azer sheds bright light in a 10-­foot radius and dim light for an additional 10 feet."}],"actions":[{"name":"Warhammer","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) bludgeoning damage, or 8 (1d10 + 3) bludgeoning damage if used with two hands to make a melee attack, plus 3 (1d6) fire damage.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"bludgeoning"}]}'),
    ('Baboon', '/icons/monsters/_mono/B.svg', 'small', 'beast', '{"name":"Baboon","size":"small","type":"beast","ac":12,"hp":3,"speed":{"walk":30,"climb":30},"abilities":{"str":8,"dex":14,"con":11,"int":4,"wis":12,"cha":6},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d6","senses":["Passive Perception 11"],"languages":["--"],"traits":[{"name":"Pack Tactics","text":"The baboon has advantage on an attack roll against a creature if at least one of the baboon''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +1 to hit, reach 5 ft., one target. Hit: 1 (1d4 − 1) piercing damage.","attackBonus":1,"reach":"5 ft"}]}'),
    ('Badger', '/icons/monsters/_mono/B.svg', 'tiny', 'beast', '{"name":"Badger","size":"tiny","type":"beast","ac":10,"hp":3,"speed":{"walk":20,"burrow":5},"abilities":{"str":4,"dex":11,"con":12,"int":2,"wis":12,"cha":5},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 + 1","senses":["Darkvision 30 ft.","Passive Perception 11"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The badger has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 1 piercing damage.","attackBonus":2,"reach":"5 ft"}]}'),
    ('Balor', '/icons/monsters/_mono/B.svg', 'huge', 'fiend', '{"name":"Balor","size":"huge","type":"fiend","ac":19,"hp":262,"speed":{"walk":40,"fly":80},"abilities":{"str":26,"dex":15,"con":22,"int":20,"wis":16,"cha":22},"cr":"19","proficiencyBonus":6,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"21d12 + 126","saves":{"str":14,"con":12,"wis":9,"cha":12},"damageResistances":["Cold","Lightning","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Truesight 120 ft.","Passive Perception 13"],"languages":["Abyssal","Telepathy 120 ft."],"traits":[{"name":"Death Throes","text":"When the balor dies, it explodes, and each creature within 30 feet of it must make a DC 20 Dexterity saving throw, taking 70 (20d6) fire damage on a failed save, or half as much damage on a successful one. The explosion ignites flammable objects in that area that aren''t being worn or carried, and it destroys the balor''s weapons."},{"name":"Fire Aura","text":"At the start of each of the balor''s turns, each creature within 5 feet of it takes 10 (3d6) fire damage, and flammable objects in the aura that aren''t being worn or carried ignite. A creature that touches the balor or hits it with a melee attack while within 5 feet of it takes 10 (3d6) fire damage."},{"name":"Magic Resistance","text":"The balor has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","text":"The balor''s weapon attacks are magical."}],"actions":[{"name":"Multiattack","text":"The balor makes two attacks: one with its longsword and one with its whip."},{"name":"Longsword","text":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 21 (3d8 + 8) slashing damage plus 13 (3d8) lightning damage. If the balor scores a critical hit, it rolls damage dice three times, instead of twice.","attackBonus":14,"reach":"10 ft","damage":"3d8+8","damageType":"slashing"},{"name":"Whip","text":"Melee Weapon Attack: +14 to hit, reach 30 ft., one target. Hit: 15 (2d6 + 8) slashing damage plus 10 (3d6) fire damage, and the target must succeed on a DC 20 Strength saving throw or be pulled up to 25 feet toward the balor.","attackBonus":14,"reach":"30 ft","damage":"2d6+8","damageType":"slashing","saveDc":20,"saveAbility":"str"},{"name":"Teleport","text":"The balor magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."}]}'),
    ('Bandit', '/icons/monsters/_mono/B.svg', 'medium', 'humanoid', '{"name":"Bandit","size":"medium","type":"humanoid","ac":12,"hp":11,"speed":{"walk":30},"abilities":{"str":11,"dex":12,"con":12,"int":10,"wis":10,"cha":10},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Leather Armor","hitDice":"2d8 + 2","senses":["Passive Perception 10"],"languages":["Any one language (usually Common)"],"actions":[{"name":"Scimitar","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) slashing damage.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"slashing"},{"name":"Light Crossbow","text":"Ranged Weapon Attack: +3 to hit, range 80 ft./320 ft., one target. Hit: 5 (1d8 + 1) piercing damage.","attackBonus":3,"damage":"1d8+1","damageType":"piercing"}]}'),
    ('Bandit Captain', '/icons/monsters/_mono/B.svg', 'medium', 'humanoid', '{"name":"Bandit Captain","size":"medium","type":"humanoid","ac":15,"hp":65,"speed":{"walk":30},"abilities":{"str":15,"dex":16,"con":14,"int":14,"wis":11,"cha":14},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Studded Leather","hitDice":"10d8 + 20","saves":{"str":4,"dex":5,"wis":2},"skills":[{"name":"Athletics","bonus":4},{"name":"Deception","bonus":4}],"senses":["Passive Perception 10"],"languages":["Any two languages"],"actions":[{"name":"Multiattack","text":"The captain makes three melee attacks: two with its scimitar and one with its dagger. Or the captain makes two ranged attacks with its daggers."},{"name":"Scimitar","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"slashing"},{"name":"Dagger","text":"Melee or Ranged Weapon Attack: +5 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 5 (1d4 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d4+3","damageType":"piercing"}],"reactions":[{"name":"Parry","text":"The captain adds 2 to its AC against one melee attack that would hit it. To do so, the captain must see the attacker and be wielding a melee weapon."}]}'),
    ('Banshee', '/icons/monsters/_mono/B.svg', 'medium', 'undead', '{"name":"Banshee","size":"medium","type":"undead","ac":12,"hp":58,"speed":{"walk":0},"abilities":{"str":1,"dex":14,"con":10,"int":12,"wis":11,"cha":17},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"13d8","saves":{"wis":2,"cha":5},"damageResistances":["Acid","Fire","Lightning","Thunder","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Cold","Necrotic","Poison"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Grappled","Paralyzed","Petrified","Poisoned","Prone","Restrained"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Common","Elvish"],"traits":[{"name":"Detect Life","text":"The banshee can magically sense the presence of creatures up to 5 miles away that aren''t undead or constructs. She knows the general direction they''re in but not their exact locations."},{"name":"Incorporeal Movement","text":"The banshee can move through other creatures and objects as if they were difficult terrain. She takes 5 (1d10) force damage if she ends her turn inside an object."}],"actions":[{"name":"Corrupting Touch","text":"Melee Spell Attack: +4 to hit, reach 5 ft., one target. Hit: 12 (3d6 + 2) necrotic damage.","attackBonus":4,"reach":"5 ft","damage":"3d6+2","damageType":"necrotic"},{"name":"Horrifying Visage","text":"Each non-undead creature within 60 feet of the banshee that can see her must succeed on a DC 13 Wisdom saving throw or be frightened for 1 minute. A frightened target can repeat the saving throw at the end of each of its turns, with disadvantage if the banshee is within line of sight, ending the effect on itself on a success. If a target''s saving throw is successful or the effect ends for it, the target is immune to the banshee''s Horrifying Visage for the next 24 hours.","saveDc":13,"saveAbility":"wis"},{"name":"Wail (1/Day)","text":"The banshee releases a mournful wail, provided that she isn''t in sunlight. This wail has no effect on constructs and undead. All other creatures within 30 feet of her that can hear her must make a DC 13 Constitution saving throw. On a failure, a creature drops to 0 hit points. On a success, a creature takes 10 (3d6) psychic damage.","saveDc":13,"saveAbility":"con"}]}'),
    ('Barbed Devil', '/icons/monsters/_mono/B.svg', 'medium', 'fiend', '{"name":"Barbed Devil","size":"medium","type":"fiend","ac":15,"hp":110,"speed":{"walk":30},"abilities":{"str":16,"dex":17,"con":18,"int":12,"wis":14,"cha":14},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"13d8 + 52","saves":{"str":6,"con":7,"wis":5,"cha":5},"skills":[{"name":"Deception","bonus":5},{"name":"Insight","bonus":5},{"name":"Perception","bonus":8}],"damageResistances":["Cold","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 18"],"languages":["Infernal","Telepathy 120 ft."],"traits":[{"name":"Barbed Hide","text":"At the start of each of its turns, the barbed devil deals 5 (1d10) piercing damage to any creature grappling it."},{"name":"Devil''s Sight","text":"Magical darkness doesn''t impede the devil''s darkvision."},{"name":"Magic Resistance","text":"The devil has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The devil makes three melee attacks: one with its tail and two with its claws. Alternatively, it can use Hurl Flame twice."},{"name":"Claw","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"1d6+3","damageType":"piercing"},{"name":"Tail","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+3","damageType":"piercing"},{"name":"Hurl Flame","text":"Ranged Spell Attack: +5 to hit, range 150 ft., one target. Hit: 10 (3d6) fire damage. If the target is a flammable object that isn''t being worn or carried, it also catches fire.","attackBonus":5,"damage":"3d6","damageType":"fire"}]}'),
    ('Basilisk', '/icons/monsters/_mono/B.svg', 'medium', 'monstrosity', '{"name":"Basilisk","size":"medium","type":"monstrosity","ac":15,"hp":52,"speed":{"walk":20},"abilities":{"str":16,"dex":8,"con":15,"int":2,"wis":8,"cha":7},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"8d8 + 16","senses":["Darkvision 60 ft.","Passive Perception 9"],"languages":["--"],"traits":[{"name":"Petrifying Gaze","text":"If a creature starts its turn within 30 feet of the basilisk and the two of them can see each other, the basilisk can force the creature to make a DC 12 Constitution saving throw if the basilisk isn''t incapacitated. On a failed save, the creature magically begins to turn to stone and is restrained. It must repeat the saving throw at the end of its next turn. On a success, the effect ends. On a failure, the creature is petrified until freed by the greater restoration spell or other magic."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage plus 7 (2d6) poison damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"piercing"}]}'),
    ('Bat', '/icons/monsters/_mono/B.svg', 'tiny', 'beast', '{"name":"Bat","size":"tiny","type":"beast","ac":12,"hp":1,"speed":{"walk":5,"fly":30},"abilities":{"str":2,"dex":15,"con":8,"int":2,"wis":12,"cha":4},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","senses":["Blindsight 60 ft.","Passive Perception 11"],"languages":["--"],"traits":[{"name":"Echolocation","text":"The bat can''t use its blindsight while deafened."},{"name":"Keen Hearing","text":"The bat has advantage on Wisdom (Perception) checks that rely on hearing."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +0 to hit, reach 5 ft., one creature. Hit: 1 piercing damage.","attackBonus":0,"reach":"5 ft"}]}'),
    ('Bearded Devil', '/icons/monsters/_mono/B.svg', 'medium', 'fiend', '{"name":"Bearded Devil","size":"medium","type":"fiend","ac":13,"hp":52,"speed":{"walk":30},"abilities":{"str":16,"dex":15,"con":15,"int":9,"wis":11,"cha":11},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"8d8 + 16","saves":{"str":5,"con":4,"wis":2},"damageResistances":["Cold","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 10"],"languages":["Infernal","Telepathy 120 ft."],"traits":[{"name":"Devil''s Sight","text":"Magical darkness doesn''t impede the devil''s darkvision."},{"name":"Magic Resistance","text":"The devil has advantage on saving throws against spells and other magical effects."},{"name":"Steadfast","text":"The devil can''t be frightened while it can see an allied creature within 30 feet of it."}],"actions":[{"name":"Multiattack","text":"The devil makes two attacks: one with its beard and one with its glaive."},{"name":"Beard","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 6 (1d8 + 2) piercing damage, and the target must succeed on a DC 12 Constitution saving throw or be poisoned for 1 minute. While poisoned in this way, the target can''t regain hit points. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attackBonus":5,"reach":"5 ft","damage":"1d8+2","damageType":"piercing","saveDc":12,"saveAbility":"con"},{"name":"Glaive","text":"Melee Weapon Attack: +5 to hit, reach 10 ft., one target. Hit: 8 (1d10 + 3) slashing damage. If the target is a creature other than an undead or a construct, it must succeed on a DC 12 Constitution saving throw or lose 5 (1d10) hit points at the start of each of its turns due to an infernal wound. Each time the devil hits the wounded target with this attack, the damage dealt by the wound increases by 5 (1d10). Any creature can take an action to stanch the wound with a successful DC 12 Wisdom (Medicine) check. The wound also closes if the target receives magical healing.","attackBonus":5,"reach":"10 ft","damage":"1d10+3","damageType":"slashing","saveDc":12,"saveAbility":"con"}]}'),
    ('Behir', '/icons/monsters/_mono/B.svg', 'huge', 'monstrosity', '{"name":"Behir","size":"huge","type":"monstrosity","ac":17,"hp":168,"speed":{"walk":50,"climb":40},"abilities":{"str":23,"dex":16,"con":18,"int":7,"wis":14,"cha":12},"cr":"11","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"16d12 + 64","skills":[{"name":"Perception","bonus":6},{"name":"Stealth","bonus":7}],"damageImmunities":["Lightning"],"senses":["Darkvision 90 ft.","Passive Perception 16"],"languages":["Draconic"],"actions":[{"name":"Multiattack","text":"The behir makes two attacks: one with its bite and one to constrict."},{"name":"Bite","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 22 (3d10 + 6) piercing damage.","attackBonus":10,"reach":"10 ft","damage":"3d10+6","damageType":"piercing"},{"name":"Constrict","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one Large or smaller creature. Hit: 17 (2d10 + 6) bludgeoning damage plus 17 (2d10 + 6) slashing damage. The target is grappled (escape DC 16) if the behir isn''t already constricting a creature, and the target is restrained until this grapple ends.","attackBonus":10,"reach":"5 ft","damage":"2d10+6","damageType":"bludgeoning"},{"name":"Lightning Breath (Recharge 5–6)","text":"The behir exhales a line of lightning that is 20 feet long and 5 feet wide. Each creature in that line must make a DC 16 Dexterity saving throw, taking 66 (12d10) lightning damage on a failed save, or half as much damage on a successful one.","saveDc":16,"saveAbility":"dex"},{"name":"Swallow","text":"The behir makes one bite attack against a Medium or smaller target it is grappling. If the attack hits, the target is also swallowed, and the grapple ends. While swallowed, the target is blinded and restrained, it has total cover against attacks and other effects outside the behir, and it takes 21 (6d6) acid damage at the start of each of the behir''s turns. A behir can have only one creature swallowed at a time."}]}'),
    ('Berserker', '/icons/monsters/_mono/B.svg', 'medium', 'humanoid', '{"name":"Berserker","size":"medium","type":"humanoid","ac":13,"hp":67,"speed":{"walk":30},"abilities":{"str":16,"dex":12,"con":17,"int":9,"wis":11,"cha":9},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Hide Armor","hitDice":"9d8 + 27","senses":["Passive Perception 10"],"languages":["Any one language (usually Common)"],"traits":[{"name":"Reckless","text":"At the start of its turn, the berserker can gain advantage on all melee weapon attack rolls during that turn, but attack rolls against it have advantage until the start of its next turn."}],"actions":[{"name":"Greataxe","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 9 (1d12 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"1d12+3","damageType":"slashing"}]}'),
    ('Black Bear', '/icons/monsters/_mono/B.svg', 'medium', 'beast', '{"name":"Black Bear","size":"medium","type":"beast","ac":11,"hp":19,"speed":{"walk":40,"climb":30},"abilities":{"str":15,"dex":10,"con":14,"int":2,"wis":12,"cha":7},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"3d8 + 6","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The bear has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Multiattack","text":"The bear makes two attacks: one with its bite and one with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":3,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) slashing damage.","attackBonus":3,"reach":"5 ft","damage":"2d4+2","damageType":"slashing"}]}'),
    ('Black Dragon Wyrmling', '/icons/monsters/_mono/B.svg', 'medium', 'dragon', '{"name":"Black Dragon Wyrmling","size":"medium","type":"dragon","ac":17,"hp":33,"speed":{"walk":30,"fly":60,"swim":30},"abilities":{"str":15,"dex":14,"con":13,"int":10,"wis":11,"cha":13},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"6d8 + 6","saves":{"dex":4,"con":3,"wis":2,"cha":3},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":4}],"damageImmunities":["Acid"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"traits":[{"name":"Amphibious","text":"The dragon can breathe air and water."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage plus 2 (1d4) acid damage.","attackBonus":4,"reach":"5 ft","damage":"1d10+2","damageType":"piercing"},{"name":"Acid Breath (Recharge 5–6)","text":"The dragon exhales acid in a 15-­foot line that is 5 feet wide. Each creature in that line must make a DC 11 Dexterity saving throw, taking 22 (5d8) acid damage on a failed save, or half as much damage on a successful one.","saveDc":11,"saveAbility":"dex"}]}'),
    ('Black Pudding', '/icons/monsters/_mono/B.svg', 'large', 'ooze', '{"name":"Black Pudding","size":"large","type":"ooze","ac":7,"hp":85,"speed":{"walk":20,"climb":20},"abilities":{"str":16,"dex":5,"con":16,"int":1,"wis":6,"cha":1},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"10d10 + 30","damageImmunities":["Acid","Cold","Lightning","Slashing"],"conditionImmunities":["Blinded","Charmed","Deafened","Exhaustion","Frightened","Prone"],"senses":["Blindsight 60 ft.","Passive Perception 8"],"languages":["--"],"traits":[{"name":"Amorphous","text":"The pudding can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Corrosive Form","text":"A creature that touches the pudding or hits it with a melee attack while within 5 feet of it takes 4 (1d8) acid damage. Any nonmagical weapon made of metal or wood that hits the pudding corrodes. After dealing damage, the weapon takes a permanent and cumulative −1 penalty to damage rolls. If its penalty drops to −5, the weapon is destroyed."},{"name":"Spider Climb","text":"The pudding can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."}],"actions":[{"name":"Pseudopod","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) bludgeoning damage plus 18 (4d8) acid damage. In addition, nonmagical armor worn by the target is partly dissolved and takes a permanent and cumulative −1 penalty to the AC it offers. The armor is destroyed if the penalty reduces its AC to 10.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"bludgeoning"}],"reactions":[{"name":"Split","text":"When a pudding that is Medium or larger is subjected to lightning or slashing damage, it splits into two new puddings if it has at least 10 hit points. Each new pudding has hit points equal to half the original pudding''s, rounded down. New puddings are one size smaller than the original pudding."}]}'),
    ('Blink Dog', '/icons/monsters/_mono/B.svg', 'medium', 'fey', '{"name":"Blink Dog","size":"medium","type":"fey","ac":13,"hp":22,"speed":{"walk":40},"abilities":{"str":12,"dex":17,"con":12,"int":10,"wis":13,"cha":11},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","hitDice":"4d8 + 4","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":5}],"senses":["Passive Perception 13"],"languages":["Blink Dog  Understands Sylvan but can''t speak it"],"traits":[{"name":"Keen Hearing and Smell","text":"The dog has advantage on Wisdom (Perception) checks that rely on hearing or smell."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) piercing damage.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"piercing"},{"name":"Teleport (Recharge 4–6)","text":"The dog magically teleports, along with any equipment it is wearing or carrying, up to 40 feet to an unoccupied space it can see. Before or after teleporting, the dog can make one bite attack."}]}'),
    ('Blood Hawk', '/icons/monsters/_mono/B.svg', 'small', 'beast', '{"name":"Blood Hawk","size":"small","type":"beast","ac":12,"hp":7,"speed":{"walk":10,"fly":60},"abilities":{"str":6,"dex":14,"con":10,"int":3,"wis":14,"cha":5},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d6","skills":[{"name":"Perception","bonus":4}],"senses":["Passive Perception 14"],"languages":["--"],"traits":[{"name":"Keen Sight","text":"The hawk has advantage on Wisdom (Perception) checks that rely on sight."},{"name":"Pack Tactics","text":"The hawk has advantage on an attack roll against a creature if at least one of the hawk''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Beak","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"piercing"}]}'),
    ('Blue Dragon Wyrmling', '/icons/monsters/_mono/B.svg', 'medium', 'dragon', '{"name":"Blue Dragon Wyrmling","size":"medium","type":"dragon","ac":17,"hp":52,"speed":{"walk":30,"burrow":15,"fly":60},"abilities":{"str":17,"dex":10,"con":15,"int":12,"wis":11,"cha":15},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"8d8 + 16","saves":{"dex":2,"con":4,"wis":2,"cha":4},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":2}],"damageImmunities":["Lightning"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (1d10 + 3) piercing damage plus 3 (1d6) lightning damage.","attackBonus":5,"reach":"5 ft","damage":"1d10+3","damageType":"piercing"},{"name":"Lightning Breath (Recharge 5–6)","text":"The dragon exhales lightning in a 30-­foot line that is 5 feet wide. Each creature in that line must make a DC 12 Dexterity saving throw, taking 22 (4d10) lightning damage on a failed save, or half as much damage on a successful one.","saveDc":12,"saveAbility":"dex"}]}'),
    ('Boar', '/icons/monsters/_mono/B.svg', 'medium', 'beast', '{"name":"Boar","size":"medium","type":"beast","ac":11,"hp":11,"speed":{"walk":40},"abilities":{"str":13,"dex":11,"con":12,"int":2,"wis":9,"cha":5},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"2d8 + 2","senses":["Passive Perception 9"],"languages":["--"],"traits":[{"name":"Charge","text":"If the boar moves at least 20 feet straight toward a target and then hits it with a tusk attack on the same turn, the target takes an extra 3 (1d6) slashing damage. If the target is a creature, it must succeed on a DC 11 Strength saving throw or be knocked prone."},{"name":"Relentless (Recharges after a Short or Long Rest)","text":"If the boar takes 7 damage or less that would reduce it to 0 hit points, it is reduced to 1 hit point instead."}],"actions":[{"name":"Tusk","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) slashing damage.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"slashing"}]}'),
    ('Bone Devil', '/icons/monsters/_mono/B.svg', 'large', 'fiend', '{"name":"Bone Devil","size":"large","type":"fiend","ac":19,"hp":142,"speed":{"walk":40,"fly":40},"abilities":{"str":18,"dex":16,"con":18,"int":13,"wis":14,"cha":16},"cr":"9","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"15d10 + 60","saves":{"int":5,"wis":6,"cha":7},"skills":[{"name":"Deception","bonus":7},{"name":"Insight","bonus":6}],"damageResistances":["Cold","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 12"],"languages":["Infernal","Telepathy 120 ft."],"traits":[{"name":"Devil''s Sight","text":"Magical darkness doesn''t impede the devil''s darkvision."},{"name":"Magic Resistance","text":"The devil has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The devil makes three attacks: two with its claws and one with its sting."},{"name":"Claw","text":"Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 8 (1d8 + 4) slashing damage.","attackBonus":8,"reach":"10 ft","damage":"1d8+4","damageType":"slashing"},{"name":"Sting","text":"Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 13 (2d8 + 4) piercing damage plus 17 (5d6) poison damage, and the target must succeed on a DC 14 Constitution saving throw or become poisoned for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attackBonus":8,"reach":"10 ft","damage":"2d8+4","damageType":"piercing","saveDc":14,"saveAbility":"con"}]}'),
    ('Brass Dragon Wyrmling', '/icons/monsters/_mono/B.svg', 'medium', 'dragon', '{"name":"Brass Dragon Wyrmling","size":"medium","type":"dragon","ac":16,"hp":16,"speed":{"walk":30,"burrow":15,"fly":60},"abilities":{"str":15,"dex":10,"con":13,"int":10,"wis":11,"cha":13},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","acNote":"Natural Armor","hitDice":"3d8 + 3","saves":{"dex":2,"con":3,"wis":2,"cha":3},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":2}],"damageImmunities":["Fire"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d10+2","damageType":"piercing"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Fire Breath","text":"The dragon exhales fire in an 20-foot line that is 5 feet wide. Each creature in that line must make a DC 11 Dexterity saving throw, taking 14 (4d6) fire damage on a failed save, or half as much damage on a successful one.","saveDc":11,"saveAbility":"dex"},{"name":"Sleep Breath","text":"The dragon exhales sleep gas in a 15-foot cone. Each creature in that area must succeed on a DC 11 Constitution saving throw or fall unconscious for 1 minute. This effect ends for a creature if the creature takes damage or someone uses an action to wake it.","saveDc":11,"saveAbility":"con"}]}'),
    ('Bronze Dragon Wyrmling', '/icons/monsters/_mono/B.svg', 'medium', 'dragon', '{"name":"Bronze Dragon Wyrmling","size":"medium","type":"dragon","ac":17,"hp":32,"speed":{"walk":30,"fly":60,"swim":30},"abilities":{"str":17,"dex":10,"con":15,"int":12,"wis":11,"cha":15},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"5d8 + 10","saves":{"dex":2,"con":4,"wis":2,"cha":4},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":2}],"damageImmunities":["Lightning"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"traits":[{"name":"Amphibious","text":"The dragon can breathe air and water."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (1d10 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d10+3","damageType":"piercing"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Lightning Breath","text":"The dragon exhales lightning in a 40-foot line that is 5 feet wide. Each creature in that line must make a DC 12 Dexterity saving throw, taking 16 (3d10) lightning damage on a failed save, or half as much damage on a successful one.","saveDc":12,"saveAbility":"dex"},{"name":"Repulsion Breath","text":"The dragon exhales repulsion energy in a 30-foot cone. Each creature in that area must succeed on a DC 12 Strength saving throw. On a failed save, the creature is pushed 30 feet away from the dragon.","saveDc":12,"saveAbility":"str"}]}'),
    ('Brown Bear', '/icons/monsters/_mono/B.svg', 'large', 'beast', '{"name":"Brown Bear","size":"large","type":"beast","ac":11,"hp":34,"speed":{"walk":40,"climb":30},"abilities":{"str":19,"dex":10,"con":16,"int":2,"wis":13,"cha":7},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"4d10 + 12","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The bear has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Multiattack","text":"The bear makes two attacks: one with its bite and one with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (1d8 + 4) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d8+4","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+4","damageType":"slashing"}]}'),
    ('Bugbear', '/icons/monsters/_mono/B.svg', 'medium', 'humanoid', '{"name":"Bugbear","size":"medium","type":"humanoid","ac":16,"hp":27,"speed":{"walk":30},"abilities":{"str":15,"dex":14,"con":13,"int":8,"wis":11,"cha":9},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Hide Armor, Shield","hitDice":"5d8 + 5","skills":[{"name":"Stealth","bonus":6},{"name":"Survival","bonus":2}],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Common","Goblin"],"traits":[{"name":"Brute","text":"A melee weapon deals one extra die of its damage when the bugbear hits with it (included in the attack)."},{"name":"Surprise Attack","text":"If the bugbear surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 7 (2d6) damage from the attack."}],"actions":[{"name":"Morningstar","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 11 (2d8 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"2d8+2","damageType":"piercing"},{"name":"Javelin","text":"Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 30/120 ft., one target. Hit: 9 (2d6 + 2) piercing damage in melee or 5 (1d6 + 2) piercing damage at range.","attackBonus":4,"reach":"5 ft","damage":"2d6+2","damageType":"piercing"}]}'),
    ('Bulette', '/icons/monsters/_mono/B.svg', 'large', 'monstrosity', '{"name":"Bulette","size":"large","type":"monstrosity","ac":17,"hp":94,"speed":{"walk":40,"burrow":40},"abilities":{"str":19,"dex":11,"con":21,"int":2,"wis":10,"cha":5},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"9d10 + 45","skills":[{"name":"Perception","bonus":6}],"senses":["Darkvision 60 ft.","Tremorsense 60 ft.","Passive Perception 16"],"languages":["--"],"traits":[{"name":"Standing Leap","text":"The bulette''s long jump is up to 30 feet and its high jump is up to 15 feet, with or without a running start."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 30 (4d12 + 4) piercing damage.","attackBonus":7,"reach":"5 ft","damage":"4d12+4","damageType":"piercing"},{"name":"Deadly Leap","text":"If the bulette jumps at least 15 feet as part of its movement, it can then use this action to land on its feet in a space that contains one or more other creatures. Each of those creatures must succeed on a DC 16 Strength or Dexterity saving throw (target''s choice) or be knocked prone and take 14 (3d6 + 4) bludgeoning damage plus 14 (3d6 + 4) slashing damage. On a successful save, the creature takes only half the damage, isn''t knocked prone, and is pushed 5 feet out of the bulette''s space into an unoccupied space of the creature''s choice. If no unoccupied space is within range, the creature instead falls prone in the bulette''s space."}]}'),
    ('Camel', '/icons/monsters/_mono/C.svg', 'large', 'beast', '{"name":"Camel","size":"large","type":"beast","ac":9,"hp":15,"speed":{"walk":50},"abilities":{"str":16,"dex":8,"con":14,"int":2,"wis":8,"cha":5},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d10 + 4","senses":["Passive Perception 9"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage.","attackBonus":5,"reach":"5 ft","damage":"1d4","damageType":"bludgeoning"}]}'),
    ('Cat', '/icons/monsters/_mono/C.svg', 'tiny', 'beast', '{"name":"Cat","size":"tiny","type":"beast","ac":12,"hp":2,"speed":{"walk":40,"climb":30},"abilities":{"str":3,"dex":15,"con":10,"int":3,"wis":12,"cha":7},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":4}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The cat has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Claws","text":"Melee Weapon Attack: +0 to hit, reach 5 ft., one target. Hit: 1 slashing damage.","attackBonus":0,"reach":"5 ft"}]}'),
    ('Centaur', '/icons/monsters/_mono/C.svg', 'large', 'monstrosity', '{"name":"Centaur","size":"large","type":"monstrosity","ac":12,"hp":45,"speed":{"walk":50},"abilities":{"str":18,"dex":14,"con":14,"int":9,"wis":13,"cha":11},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral good","hitDice":"6d10 + 12","skills":[{"name":"Athletics","bonus":6},{"name":"Perception","bonus":3},{"name":"Survival","bonus":3}],"senses":["Passive Perception 13"],"languages":["Elvish","Sylvan"],"traits":[{"name":"Charge","text":"If the centaur moves at least 30 feet straight toward a target and then hits it with a pike attack on the same turn, the target takes an extra 10 (3d6) piercing damage."}],"actions":[{"name":"Multiattack","text":"The centaur makes two attacks: one with its pike and one with its hooves or two with its longbow."},{"name":"Pike","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 9 (1d10 + 4) piercing damage.","attackBonus":6,"reach":"10 ft","damage":"1d10+4","damageType":"piercing"},{"name":"Hooves","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+4","damageType":"bludgeoning"},{"name":"Longbow","text":"Ranged Weapon Attack: +4 to hit, range 150/600 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","attackBonus":4,"reach":"range 150/600 ft","damage":"1d8+2","damageType":"piercing"}]}'),
    ('Chain Devil', '/icons/monsters/_mono/C.svg', 'medium', 'fiend', '{"name":"Chain Devil","size":"medium","type":"fiend","ac":16,"hp":85,"speed":{"walk":30},"abilities":{"str":18,"dex":15,"con":18,"int":11,"wis":12,"cha":14},"cr":"8","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"10d8 + 40","saves":{"con":7,"wis":4,"cha":5},"damageResistances":["Cold","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 11"],"languages":["Infernal","Telepathy 120 ft."],"traits":[{"name":"Devil''s Sight","text":"Magical darkness doesn''t impede the devil''s darkvision."},{"name":"Magic Resistance","text":"The devil has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The devil makes two attacks with its chains."},{"name":"Chain","text":"Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 11 (2d6 + 4) slashing damage. The target is grappled (escape DC 14) if the devil isn''t already grappling a creature. Until this grapple ends, the target is restrained and takes 7 (2d6) piercing damage at the start of each of its turns.","attackBonus":8,"reach":"10 ft","damage":"2d6+4","damageType":"slashing"},{"name":"Animate Chains (Recharges after a Short or Long Rest)","text":"Up to four chains the devil can see within 60 feet of it magically sprout razor-­edged barbs and animate under the devil''s control, provided that the chains aren''t being worn or carried."}],"reactions":[{"name":"Unnerving Mask","text":"When a creature the devil can see starts its turn within 30 feet of the devil, the devil can create the illusion that it looks like one of the creature''s departed loved ones or bitter enemies. If the creature can see the devil, it must succeed on a DC 14 Wisdom saving throw or be frightened until the end of its turn."}]}'),
    ('Chimera', '/icons/monsters/_mono/C.svg', 'large', 'monstrosity', '{"name":"Chimera","size":"large","type":"monstrosity","ac":14,"hp":114,"speed":{"walk":30,"fly":60},"abilities":{"str":19,"dex":11,"con":19,"int":3,"wis":14,"cha":10},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"12d10 + 48","skills":[{"name":"Perception","bonus":8}],"senses":["Darkvision 60 ft.","Passive Perception 18"],"languages":["Understands Draconic but can''t speak  it"],"actions":[{"name":"Multiattack","text":"The chimera makes three attacks: one with its bite, one with its horns, and one with its claws. When its fire breath is available, it can use the breath in place of its bite or horns."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) piercing damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"piercing"},{"name":"Horns","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 10 (1d12 + 4) bludgeoning damage.","attackBonus":7,"reach":"5 ft","damage":"1d12+4","damageType":"bludgeoning"},{"name":"Claws","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"slashing"},{"name":"Fire Breath (Recharge 5–6)","text":"The dragon head exhales fire in a 15-­-foot cone. Each creature in that area must make a DC 15 Dexterity saving throw, taking 31 (7d8) fire damage on a failed save, or half as much damage on a successful one.","saveDc":15,"saveAbility":"dex"}]}'),
    ('Chuul', '/icons/monsters/_mono/C.svg', 'large', 'aberration', '{"name":"Chuul","size":"large","type":"aberration","ac":16,"hp":93,"speed":{"walk":30,"swim":30},"abilities":{"str":19,"dex":10,"con":16,"int":5,"wis":11,"cha":5},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"11d10 + 33","skills":[{"name":"Perception","bonus":4}],"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["Understands Deep Speech but can''t speak"],"traits":[{"name":"Amphibious","text":"The chuul can breathe air and water."},{"name":"Sense Magic","text":"The chuul senses magic within 120 feet of it at will. This trait otherwise works like the detect magic spell but isn''t itself magical."}],"actions":[{"name":"Multiattack","text":"The chuul makes two pincer attacks. If the chuul is grappling a creature, the chuul can also use its tentacles once."},{"name":"Pincer","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage. The target is grappled (escape DC 14) if it is a Large or smaller creature and the chuul doesn''t have two other creatures grappled.","attackBonus":6,"reach":"10 ft","damage":"2d6+4","damageType":"bludgeoning"},{"name":"Tentacles","text":"One creature grappled by the chuul must succeed on a DC 13 Constitution saving throw or be poisoned for 1 minute. Until this poison ends, the target is paralyzed. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","saveDc":13,"saveAbility":"con"}]}'),
    ('Clay Golem', '/icons/monsters/_mono/C.svg', 'large', 'construct', '{"name":"Clay Golem","size":"large","type":"construct","ac":14,"hp":133,"speed":{"walk":20},"abilities":{"str":20,"dex":9,"con":18,"int":3,"wis":8,"cha":1},"cr":"9","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"14d10 + 56","damageImmunities":["Acid","Poison","Psychic","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Adamantine"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Paralyzed","Petrified","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 9"],"languages":["Understands the languages of its creator but can''t speak"],"traits":[{"name":"Acid Absorption","text":"Whenever the golem is subjected to acid damage, it takes no damage and instead regains a number of hit points equal to the acid damage dealt."},{"name":"Berserk","text":"Whenever the golem starts its turn with 60 hit points or fewer, roll a d6. On a 6, the golem goes berserk. On each of its turns while berserk, the golem attacks the nearest creature it can see. If no creature is near enough to move to and attack, the golem attacks an object, with preference for an object smaller than itself. Once the golem goes berserk, it continues to do so until it is destroyed or regains all its hit points."},{"name":"Immutable Form","text":"The golem is immune to any spell or effect that would alter its form."},{"name":"Magic Resistance","text":"The golem has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","text":"The golem''s weapon attacks are magical."}],"actions":[{"name":"Multiattack","text":"The golem makes two slam attacks."},{"name":"Slam","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 16 (2d10 + 5) bludgeoning damage. If the target is a creature, it must succeed on a DC 15 Constitution saving throw or have its hit point maximum reduced by an amount equal to the damage taken. The target dies if this attack reduces its hit point maximum to 0. The reduction lasts until removed by the greater restoration spell or other magic.","attackBonus":8,"reach":"5 ft","damage":"2d10+5","damageType":"bludgeoning","saveDc":15,"saveAbility":"con"},{"name":"Haste (Recharge 5–6)","text":"Until the end of its next turn, the golem magically gains a +2 bonus to its AC, has advantage on Dexterity saving throws, and can use its slam attack as a bonus action."}]}'),
    ('Cloaker', '/icons/monsters/_mono/C.svg', 'large', 'aberration', '{"name":"Cloaker","size":"large","type":"aberration","ac":14,"hp":78,"speed":{"walk":10,"fly":40},"abilities":{"str":17,"dex":15,"con":12,"int":13,"wis":12,"cha":14},"cr":"8","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic neutral","acNote":"Natural Armor","hitDice":"12d10 + 12","skills":[{"name":"Stealth","bonus":5}],"senses":["Darkvision 60 ft.","Passive Perception 11"],"languages":["Deep Speech","Undercommon"],"traits":[{"name":"Damage Transfer","text":"While attached to a creature, the cloaker takes only half the damage dealt to it (rounded down), and that creature takes the other half."},{"name":"False Appearance","text":"While the cloaker remains motionless without its underside exposed, it is indistinguishable from a dark leather cloak."},{"name":"Light Sensitivity","text":"While in bright light, the cloaker has disadvantage on attack rolls and Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Multiattack","text":"The cloaker makes two attacks: one with its bite and one with its tail."},{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one creature. Hit: 10 (2d6 + 3) piercing damage, and if the target is Large or smaller, the cloaker attaches to it. If the cloaker has advantage against the target, the cloaker attaches to the target''s head, and the target is blinded and unable to breathe while the cloaker is attached. While attached, the cloaker can make this attack only against the target and has advantage on the attack roll. The cloaker can detach itself by spending 5 feet of its movement. A creature, including the target, can take its action to detach the cloaker by succeeding on a DC 16 Strength check.","attackBonus":6,"reach":"5 ft","damage":"2d6+3","damageType":"piercing"},{"name":"Tail","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one creature. Hit: 7 (1d8 + 3) slashing damage.","attackBonus":6,"reach":"10 ft","damage":"1d8+3","damageType":"slashing"},{"name":"Moan","text":"Each creature within 60 feet of the cloaker that can hear its moan and that isn''t an aberration must succeed on a DC 13 Wisdom saving throw or become frightened until the end of the cloaker''s next turn. If a creature''s saving throw is successful, the creature is immune to the cloaker''s moan for the next 24 hours.","saveDc":13,"saveAbility":"wis"},{"name":"Phantasms (Recharges after a Short or Long Rest)","text":"The cloaker magically creates three illusory duplicates of itself if it isn''t in bright light. The duplicates move with it and mimic its actions, shifting position so as to make it impossible to track which cloaker is the real one. If the cloaker is ever in an area of bright light, the duplicates disappear."}]}'),
    ('Cloud Giant', '/icons/monsters/_mono/C.svg', 'huge', 'giant', '{"name":"Cloud Giant","size":"huge","type":"giant","ac":14,"hp":200,"speed":{"walk":40},"abilities":{"str":27,"dex":10,"con":22,"int":12,"wis":16,"cha":16},"cr":"9","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"16d12 + 96","saves":{"con":10,"wis":7,"cha":7},"skills":[{"name":"Insight","bonus":7},{"name":"Perception","bonus":7}],"senses":["Passive Perception 17"],"languages":["Common","Giant"],"traits":[{"name":"Keen Smell","text":"The giant has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Innate Spellcasting","text":"The giant''s innate spellcasting ability is Charisma. It can innately cast the following spells, requiring no material components:"}],"actions":[{"name":"Multiattack","text":"The giant makes two morningstar attacks."},{"name":"Morningstar","text":"Melee Weapon Attack: +12 to hit, reach 10 ft., one target. Hit: 21 (3d8 + 8) piercing damage.","attackBonus":12,"reach":"10 ft","damage":"3d8+8","damageType":"piercing"},{"name":"Rock","text":"Ranged Weapon Attack: +12 to hit, range 60/240 ft., one target. Hit: 30 (4d10 + 8) bludgeoning damage.","attackBonus":12,"reach":"range 60/240 ft","damage":"4d10+8","damageType":"bludgeoning"}]}'),
    ('Cockatrice', '/icons/monsters/_mono/C.svg', 'small', 'monstrosity', '{"name":"Cockatrice","size":"small","type":"monstrosity","ac":11,"hp":27,"speed":{"walk":20,"fly":40},"abilities":{"str":6,"dex":12,"con":12,"int":2,"wis":13,"cha":5},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"6d6 + 6","senses":["Darkvision 60 ft.","Passive Perception 11"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 3 (1d4 + 1) piercing damage, and the target must succeed on a DC 11 Constitution saving throw against being magically petrified. On a failed save, the creature begins to turn to stone and is restrained. It must repeat the saving throw at the end of its next turn. On a success, the effect ends. On a failure, the creature is petrified for 24 hours.","attackBonus":3,"reach":"5 ft","damage":"1d4+1","damageType":"piercing","saveDc":11,"saveAbility":"con"}]}'),
    ('Commoner', '/icons/monsters/_mono/C.svg', 'medium', 'humanoid', '{"name":"Commoner","size":"medium","type":"humanoid","ac":10,"hp":4,"speed":{"walk":30},"abilities":{"str":10,"dex":10,"con":10,"int":10,"wis":10,"cha":10},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","hitDice":"1d8","senses":["Passive Perception 10"],"languages":["Any one language (usually Common)"],"actions":[{"name":"Club","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage.","attackBonus":2,"reach":"5 ft","damage":"1d4","damageType":"bludgeoning"}]}'),
    ('Constrictor Snake', '/icons/monsters/_mono/C.svg', 'large', 'beast', '{"name":"Constrictor Snake","size":"large","type":"beast","ac":12,"hp":13,"speed":{"walk":30,"swim":30},"abilities":{"str":15,"dex":14,"con":12,"int":1,"wis":10,"cha":3},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d10 + 2","senses":["Blindsight 10 ft.","Passive Perception 10"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Constrict","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 6 (1d8 + 2) bludgeoning damage, and the target is grappled (escape DC 14). Until this grapple ends, the creature is restrained, and the snake can''t constrict another target.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"bludgeoning"}]}'),
    ('Copper Dragon Wyrmling', '/icons/monsters/_mono/C.svg', 'medium', 'dragon', '{"name":"Copper Dragon Wyrmling","size":"medium","type":"dragon","ac":16,"hp":22,"speed":{"walk":30,"climb":30,"fly":60},"abilities":{"str":15,"dex":12,"con":13,"int":14,"wis":11,"cha":13},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","acNote":"Natural Armor","hitDice":"4d8 + 4","saves":{"dex":3,"con":3,"wis":2,"cha":3},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":3}],"damageImmunities":["Acid"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d10+2","damageType":"piercing"},{"name":"Breath Weapons (Recharge 5–6)","text":"The dragon uses one of the following breath weapons."},{"name":"Acid Breath","text":"The dragon exhales acid in an 20-foot line that is 5 feet wide. Each creature in that line must make a DC 11 Dexterity saving throw, taking 18 (4d8) acid damage on a failed save, or half as much damage on a successful one.","saveDc":11,"saveAbility":"dex"},{"name":"Slowing Breath","text":"The dragon exhales gas in a 15-foot cone. Each creature in that area must succeed on a DC 11 Constitution saving throw. On a failed save, the creature can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the creature can use either an action or a bonus action on its turn, but not both. These effects last for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself with a successful save.","saveDc":11,"saveAbility":"con"}]}'),
    ('Couatl', '/icons/monsters/_mono/C.svg', 'medium', 'celestial', '{"name":"Couatl","size":"medium","type":"celestial","ac":19,"hp":97,"speed":{"walk":30,"fly":90},"abilities":{"str":16,"dex":20,"con":17,"int":18,"wis":20,"cha":18},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"13d8 + 39","saves":{"con":5,"wis":7,"cha":6},"damageResistances":["Radiant"],"damageImmunities":["Psychic","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"senses":["Truesight 120 ft.","Passive Perception 15"],"languages":["All","Telepathy 120 ft."],"traits":[{"name":"Innate Spellcasting","text":"The couatl''s spellcasting ability is Charisma (spell save DC 14). It can innately cast the following spells, requiring only verbal components:"},{"name":"Magic Weapons","text":"The couatl''s weapon attacks are magical."},{"name":"Shielded Mind","text":"The couatl is immune to scrying and to any effect that would sense its emotions, read its thoughts, or detect its location."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one creature. Hit: 8 (1d6 + 5) piercing damage, and the target must succeed on a DC 13 Constitution saving throw or be poisoned for 24 hours. Until this poison ends, the target is unconscious. Another creature can use an action to shake the target awake.","attackBonus":8,"reach":"5 ft","damage":"1d6+5","damageType":"piercing","saveDc":13,"saveAbility":"con"},{"name":"Constrict","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one Medium or smaller creature. Hit: 10 (2d6 + 3) bludgeoning damage, and the target is grappled (escape DC 15). Until this grapple ends, the target is restrained, and the couatl can''t constrict another target.","attackBonus":6,"reach":"10 ft","damage":"2d6+3","damageType":"bludgeoning"},{"name":"Change Shape","text":"The couatl magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the couatl''s choice)."}]}'),
    ('Crab', '/icons/monsters/_mono/C.svg', 'tiny', 'beast', '{"name":"Crab","size":"tiny","type":"beast","ac":11,"hp":2,"speed":{"walk":20,"swim":20},"abilities":{"str":2,"dex":11,"con":10,"int":1,"wis":8,"cha":2},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"1d4","skills":[{"name":"Stealth","bonus":2}],"senses":["Blindsight 30 ft.","Passive Perception 9"],"languages":["--"],"traits":[{"name":"Amphibious","text":"The crab can breathe air and water."}],"actions":[{"name":"Claw","text":"Melee Weapon Attack: +0 to hit, reach 5 ft., one target. Hit: 1 bludgeoning damage.","attackBonus":0,"reach":"5 ft"}]}'),
    ('Crocodile', '/icons/monsters/_mono/C.svg', 'large', 'beast', '{"name":"Crocodile","size":"large","type":"beast","ac":12,"hp":19,"speed":{"walk":20,"swim":30},"abilities":{"str":15,"dex":10,"con":13,"int":2,"wis":10,"cha":5},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"3d10 + 3","skills":[{"name":"Stealth","bonus":2}],"senses":["Passive Perception 10"],"languages":["--"],"traits":[{"name":"Hold Breath","text":"The crocodile can hold its breath for 15 minutes."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 7 (1d10 + 2) piercing damage, and the target is grappled (escape DC 12). Until this grapple ends, the target is restrained, and the crocodile can''t bite another target.","attackBonus":4,"reach":"5 ft","damage":"1d10+2","damageType":"piercing"}]}'),
    ('Cult Fanatic', '/icons/monsters/_mono/C.svg', 'medium', 'humanoid', '{"name":"Cult Fanatic","size":"medium","type":"humanoid","ac":13,"hp":33,"speed":{"walk":30},"abilities":{"str":11,"dex":14,"con":12,"int":10,"wis":13,"cha":14},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Leather Armor","hitDice":"6d8 + 6","skills":[{"name":"Deception","bonus":4},{"name":"Persuasion","bonus":4},{"name":"Religion","bonus":2}],"senses":["Passive Perception 11"],"languages":["Any one language (usually Common)"],"traits":[{"name":"Dark Devotion","text":"The fanatic has advantage on saving throws against being charmed or frightened."},{"name":"Spellcasting","text":"The fanatic is a 4th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 11, +3 to hit with spell attacks). The fanatic has the following cleric spells prepared:"}],"actions":[{"name":"Multiattack","text":"The fanatic makes two melee attacks."},{"name":"Dagger","text":"Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 20/60 ft., one creature. Hit: 4 (1d4 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"piercing"}]}'),
    ('Cultist', '/icons/monsters/_mono/C.svg', 'medium', 'humanoid', '{"name":"Cultist","size":"medium","type":"humanoid","ac":12,"hp":9,"speed":{"walk":30},"abilities":{"str":11,"dex":12,"con":10,"int":10,"wis":11,"cha":10},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Leather Armor","hitDice":"2d8","skills":[{"name":"Deception","bonus":2},{"name":"Religion","bonus":2}],"senses":["Passive Perception 10"],"languages":["Any one language (usually Common)"],"traits":[{"name":"Dark Devotion","text":"The cultist has advantage on saving throws against being charmed or frightened."}],"actions":[{"name":"Scimitar","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 4 (1d6 + 1) slashing damage.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"slashing"}]}'),
    ('Cyclops', '/icons/monsters/_mono/C.svg', 'huge', 'giant', '{"name":"Cyclops","size":"huge","type":"giant","ac":14,"hp":138,"speed":{"walk":30},"abilities":{"str":22,"dex":11,"con":20,"int":8,"wis":6,"cha":10},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic neutral","hitDice":"12d12 + 60","senses":["Passive Perception 8"],"languages":["Giant"],"traits":[{"name":"Poor Depth Perception","text":"The cyclops has disadvantage on any attack roll against a target more than 30 feet away."}],"actions":[{"name":"Multiattack","text":"The cyclops makes two greatclub attacks."},{"name":"Greatclub","text":"Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 19 (3d8 + 6) bludgeoning damage.","attackBonus":9,"reach":"10 ft","damage":"3d8+6","damageType":"bludgeoning"},{"name":"Rock","text":"Ranged Weapon Attack: +9 to hit, range 30/120 ft., one target. Hit: 28 (4d10 + 6) bludgeoning damage.","attackBonus":9,"reach":"range 30/120 ft","damage":"4d10+6","damageType":"bludgeoning"}]}'),
    ('Darkmantle', '/icons/monsters/_mono/D.svg', 'small', 'monstrosity', '{"name":"Darkmantle","size":"small","type":"monstrosity","ac":11,"hp":22,"speed":{"walk":10,"fly":30},"abilities":{"str":16,"dex":12,"con":13,"int":2,"wis":10,"cha":5},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"5d6 + 5","skills":[{"name":"Stealth","bonus":3}],"senses":["Blindsight 60 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Echolocation","text":"The darkmantle can''t use its blindsight while deafened."},{"name":"False Appearance","text":"While the darkmantle remains motionless, it is indistinguishable from a cave formation such as a stalactite or stalagmite."}],"actions":[{"name":"Crush","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 6 (1d6 + 3) bludgeoning damage, and the darkmantle attaches to the target. If the target is Medium or smaller and the darkmantle has advantage on the attack roll, it attaches by engulfing the target''s head, and the target is also blinded and unable to breathe while the darkmantle is attached in this way.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"bludgeoning"},{"name":"Darkness Aura (1/Day)","text":"A 15-­-foot radius of magical darkness extends out from the darkmantle, moves with it, and spreads around corners. The darkness lasts as long as the darkmantle maintains concentration, up to 10 minutes (as if concentrating on a spell). Darkvision can''t penetrate this darkness, and no natural light can illuminate it. If any of the darkness overlaps with an area of light created by a spell of 2nd level or lower, the spell creating the light is dispelled."}]}'),
    ('Death Dog', '/icons/monsters/_mono/D.svg', 'medium', 'monstrosity', '{"name":"Death Dog","size":"medium","type":"monstrosity","ac":12,"hp":39,"speed":{"walk":40},"abilities":{"str":15,"dex":14,"con":14,"int":3,"wis":13,"cha":6},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"6d8 + 12","skills":[{"name":"Perception","bonus":5},{"name":"Stealth","bonus":4}],"senses":["Darkvision 120 ft.","Passive Perception 15"],"languages":["--"],"traits":[{"name":"Two-Headed","text":"The dog has advantage on Wisdom (Perception) checks and on saving throws against being blinded, charmed, deafened, frightened, stunned, or knocked unconscious."}],"actions":[{"name":"Multiattack","text":"The dog makes two bite attacks."},{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage. If the target is a creature, it must succeed on a DC 12 Constitution saving throw against disease or become poisoned until the disease is cured. Every 24 hours that elapse, the creature must repeat the saving throw, reducing its hit point maximum by 5 (1d10) on a failure. This reduction lasts until the disease is cured. The creature dies if the disease reduces its hit point maximum to 0.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing","saveDc":12,"saveAbility":"con"}]}'),
    ('Deep Gnome (Svirfneblin)', '/icons/monsters/_mono/D.svg', 'small', 'humanoid', '{"name":"Deep Gnome (Svirfneblin)","size":"small","type":"humanoid","ac":15,"hp":16,"speed":{"walk":20},"abilities":{"str":15,"dex":14,"con":14,"int":12,"wis":10,"cha":9},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral good","acNote":"Chain Shirt","hitDice":"3d6 + 6","skills":[{"name":"Investigation","bonus":3},{"name":"Perception","bonus":2},{"name":"Stealth","bonus":4}],"senses":["Darkvision 120 ft.","Passive Perception 12"],"languages":["Gnomish","Terran","Undercommon"],"traits":[{"name":"Stone Camouflage","text":"The gnome has advantage on Dexterity (Stealth) checks made to hide in rocky terrain."},{"name":"Gnome Cunning","text":"The gnome has advantage on Intelligence, Wisdom, and Charisma saving throws against magic."},{"name":"Innate Spellcasting","text":"The gnome''s innate spellcasting ability is Intelligence (spell save DC 11). It can innately cast the following spells, requiring no material components:"}],"actions":[{"name":"War Pick","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"piercing"},{"name":"Poisoned Dart","text":"Ranged Weapon Attack: +4 to hit, range 30/120 ft., one creature. Hit: 4 (1d4 + 2) piercing damage, and the target must succeed on a DC 12 Constitution saving throw or be poisoned for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attackBonus":4,"reach":"range 30/120 ft","damage":"1d4+2","damageType":"piercing","saveDc":12,"saveAbility":"con"}]}'),
    ('Deer', '/icons/monsters/_mono/D.svg', 'medium', 'beast', '{"name":"Deer","size":"medium","type":"beast","ac":13,"hp":4,"speed":{"walk":50},"abilities":{"str":11,"dex":16,"con":11,"int":2,"wis":14,"cha":5},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d8","senses":["Passive Perception 12"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 2 (1d4) piercing damage.","attackBonus":2,"reach":"5 ft","damage":"1d4","damageType":"piercing"}]}'),
    ('Deva', '/icons/monsters/_mono/D.svg', 'medium', 'celestial', '{"name":"Deva","size":"medium","type":"celestial","ac":17,"hp":136,"speed":{"walk":30,"fly":90},"abilities":{"str":18,"dex":18,"con":18,"int":17,"wis":20,"cha":20},"cr":"10","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"16d8 + 64","saves":{"wis":9,"cha":9},"skills":[{"name":"Insight","bonus":9},{"name":"Perception","bonus":9}],"damageResistances":["Radiant","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"conditionImmunities":["Charmed","Exhaustion","Frightened"],"senses":["Darkvision 120 ft.","Passive Perception 19"],"languages":["All","Telepathy 120 ft."],"traits":[{"name":"Angelic Weapons","text":"The deva''s weapon attacks are magical. When the deva hits with any weapon, the weapon deals an extra 4d8 radiant damage (included in the attack)."},{"name":"Innate Spellcasting","text":"The deva''s spellcasting ability is Charisma (spell save DC 17). The deva can innately cast the following spells, requiring only verbal components:"},{"name":"Magic Resistance","text":"The deva has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The deva makes two melee attacks."},{"name":"Mace","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) bludgeoning damage plus 18 (4d8) radiant damage.","attackBonus":8,"reach":"5 ft","damage":"1d6+4","damageType":"bludgeoning"},{"name":"Healing Touch (3/Day)","text":"The deva touches another creature. The target magically regains 20 (4d8 + 2) hit points and is freed from any curse, disease, poison, blindness, or deafness."},{"name":"Change Shape","text":"The deva magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the deva''s choice)."}]}'),
    ('Dire Wolf', '/icons/monsters/_mono/D.svg', 'large', 'beast', '{"name":"Dire Wolf","size":"large","type":"beast","ac":14,"hp":37,"speed":{"walk":50},"abilities":{"str":17,"dex":15,"con":15,"int":3,"wis":12,"cha":7},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"5d10 + 10","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":4}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Hearing and Smell","text":"The wolf has advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Pack Tactics","text":"The wolf has advantage on an attack roll against a creature if at least one of the wolf''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"piercing","saveDc":13,"saveAbility":"str"}]}'),
    ('Djinni', '/icons/monsters/_mono/D.svg', 'large', 'elemental', '{"name":"Djinni","size":"large","type":"elemental","ac":17,"hp":161,"speed":{"walk":30,"fly":90},"abilities":{"str":21,"dex":15,"con":22,"int":15,"wis":16,"cha":20},"cr":"11","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic good","acNote":"Natural Armor","hitDice":"14d10 + 84","saves":{"dex":6,"wis":7,"cha":9},"damageImmunities":["Lightning","Thunder"],"senses":["Darkvision 120 ft.","Passive Perception 13"],"languages":["Auran"],"traits":[{"name":"Elemental Demise","text":"If the djinni dies, its body disintegrates into a warm breeze, leaving behind only equipment the djinni was wearing or carrying."},{"name":"Innate Spellcasting","text":"The djinni''s innate spellcasting ability is Charisma (spell save DC 17, +9 to hit with spell attacks). It can innately cast the following spells, requiring no material components:"}],"actions":[{"name":"Multiattack","text":"The djinni makes three scimitar attacks."},{"name":"Scimitar","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) slashing damage plus 3 (1d6) lightning or thunder damage (djinni''s choice).","attackBonus":9,"reach":"5 ft","damage":"2d6+5","damageType":"slashing"},{"name":"Create Whirlwind","text":"A 5-foot-radius, 30-foot-tall cylinder of swirling air magically forms on a point the djinni can see within 120 feet of it. The whirlwind lasts as long as the djinni maintains concentration (as if concentrating on a spell). Any creature but the djinni that enters the whirlwind must succeed on a DC 18 Strength saving throw or be restrained by it. The djinni can move the whirlwind up to 60 feet as an action, and creatures restrained by the whirlwind move with it. The whirlwind ends if the djinni loses sight of it.","saveDc":18,"saveAbility":"str"}]}'),
    ('Doppelganger', '/icons/monsters/_mono/D.svg', 'medium', 'monstrosity', '{"name":"Doppelganger","size":"medium","type":"monstrosity","ac":14,"hp":52,"speed":{"walk":30},"abilities":{"str":11,"dex":18,"con":14,"int":11,"wis":12,"cha":14},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"8d8 + 16","skills":[{"name":"Deception","bonus":6},{"name":"Insight","bonus":3}],"conditionImmunities":["Charmed"],"senses":["Darkvision 60 ft.","Passive Perception 11"],"languages":["Common"],"traits":[{"name":"Shapechanger","text":"The doppelganger can use its action to polymorph into a Small or Medium humanoid it has seen, or back into its true form. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Ambusher","text":"The doppelganger has advantage on attack rolls against any creature it has surprised."},{"name":"Surprise Attack","text":"If the doppelganger surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 10 (3d6) damage from the attack."}],"actions":[{"name":"Multiattack","text":"The doppelganger makes two melee attacks."},{"name":"Slam","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"1d6+4","damageType":"bludgeoning"},{"name":"Read Thoughts","text":"The doppelganger magically reads the surface thoughts of one creature within 60 feet of it. The effect can penetrate barriers, but 3 feet of wood or dirt, 2 feet of stone, 2 inches of metal, or a thin sheet of lead blocks it. While the target is in range, the doppelganger can continue reading its thoughts, as long as the doppelganger''s concentration isn''t broken (as if concentrating on a spell). While reading the target''s mind, the doppelganger has advantage on Wisdom (Insight) and Charisma (Deception, Intimidation, and Persuasion) checks against the target."}]}'),
    ('Draft Horse', '/icons/monsters/_mono/D.svg', 'large', 'beast', '{"name":"Draft Horse","size":"large","type":"beast","ac":10,"hp":19,"speed":{"walk":40},"abilities":{"str":18,"dex":10,"con":12,"int":2,"wis":11,"cha":7},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d10 + 3","senses":["Passive Perception 10"],"languages":["--"],"actions":[{"name":"Hooves","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (2d4 + 4) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"2d4+4","damageType":"bludgeoning"}]}'),
    ('Dragon Turtle', '/icons/monsters/_mono/D.svg', 'gargantuan', 'dragon', '{"name":"Dragon Turtle","size":"gargantuan","type":"dragon","ac":20,"hp":341,"speed":{"walk":20,"swim":40},"abilities":{"str":25,"dex":10,"con":20,"int":10,"wis":12,"cha":12},"cr":"17","proficiencyBonus":6,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"22d20 + 110","saves":{"dex":6,"con":11,"wis":7},"damageResistances":["Fire"],"senses":["Darkvision 120 ft.","Passive Perception 11"],"languages":["Aquan","Draconic"],"traits":[{"name":"Amphibious","text":"The dragon turtle can breathe air and water."}],"actions":[{"name":"Multiattack","text":"The dragon turtle makes three attacks: one with its bite and two with its claws. It can make one tail attack in place of its two claw attacks."},{"name":"Bite","text":"Melee Weapon Attack: +13 to hit, reach 15 ft., one target. Hit: 26 (3d12 + 7) piercing damage.","attackBonus":13,"reach":"15 ft","damage":"3d12+7","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +13 to hit, reach 10 ft., one target. Hit: 16 (2d8 + 7) slashing damage.","attackBonus":13,"reach":"10 ft","damage":"2d8+7","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +13 to hit, reach 15 ft., one target. Hit: 26 (3d12 + 7) bludgeoning damage. If the target is a creature, it must succeed on a DC 20 Strength saving throw or be pushed up to 10 feet away from the dragon turtle and knocked prone.","attackBonus":13,"reach":"15 ft","damage":"3d12+7","damageType":"bludgeoning","saveDc":20,"saveAbility":"str"},{"name":"Steam Breath (Recharge 5–6)","text":"The dragon turtle exhales scalding steam in a 60-foot cone. Each creature in that area must make a DC 18 Constitution saving throw, taking 52 (15d6) fire damage on a failed save, or half as much damage on a successful one. Being underwater doesn''t grant resistance against this damage.","saveDc":18,"saveAbility":"con"}]}'),
    ('Dretch', '/icons/monsters/_mono/D.svg', 'small', 'fiend', '{"name":"Dretch","size":"small","type":"fiend","ac":11,"hp":18,"speed":{"walk":20},"abilities":{"str":11,"dex":11,"con":12,"int":5,"wis":8,"cha":3},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"4d6 + 4","damageResistances":["Cold","Fire","Lightning"],"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 9"],"languages":["Abyssal","Telepathy 60 ft."],"actions":[{"name":"Multiattack","text":"The dretch makes two attacks: one with its bite and one with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 3 (1d6) piercing damage.","attackBonus":2,"reach":"5 ft","damage":"1d6","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 5 (2d4) slashing damage.","attackBonus":2,"reach":"5 ft","damage":"2d4","damageType":"slashing"},{"name":"Fetid Cloud (1/Day)","text":"A 10­-foot radius of disgusting green gas extends out from the dretch. The gas spreads around corners, and its area is lightly obscured. It lasts for 1 minute or until a strong wind disperses it. Any creature that starts its turn in that area must succeed on a DC 11 Constitution saving throw or be poisoned until the start of its next turn. While poisoned in this way, the target can take either an action or a bonus action on its turn, not both, and can''t take reactions.","saveDc":11,"saveAbility":"con"}]}'),
    ('Drider', '/icons/monsters/_mono/D.svg', 'large', 'monstrosity', '{"name":"Drider","size":"large","type":"monstrosity","ac":19,"hp":123,"speed":{"walk":30,"climb":30},"abilities":{"str":16,"dex":16,"con":18,"int":13,"wis":14,"cha":12},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"13d10 + 52","skills":[{"name":"Perception","bonus":5},{"name":"Stealth","bonus":9}],"senses":["Darkvision 120 ft.","Passive Perception 15"],"languages":["Elvish","Undercommon"],"traits":[{"name":"Fey Ancestry","text":"The drider has advantage on saving throws against being charmed, and magic can''t put the drider to sleep."},{"name":"Innate Spellcasting","text":"The drider''s innate spellcasting ability is Wisdom (spell save DC 13). The drider can innately cast the following spells, requiring no material components:"},{"name":"Spider Climb","text":"The drider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Sunlight Sensitivity","text":"While in sunlight, the drider has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."},{"name":"Web Walker","text":"The drider ignores movement restrictions caused by webbing."}],"actions":[{"name":"Multiattack","text":"The drider makes three attacks, either with its longsword or its longbow. It can replace one of those attacks with a bite attack."},{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one creature. Hit: 2 (1d4) piercing damage plus 9 (2d8) poison damage.","attackBonus":6,"reach":"5 ft","damage":"1d4","damageType":"piercing"},{"name":"Longsword","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) slashing damage, or 8 (1d10 + 3) slashing damage if used with two hands.","attackBonus":6,"reach":"5 ft","damage":"1d8+3","damageType":"slashing"},{"name":"Longbow","text":"Ranged Weapon Attack: +6 to hit, range 150/600 ft., one target. Hit: 7 (1d8 + 3) piercing damage plus 4 (1d8) poison damage.","attackBonus":6,"reach":"range 150/600 ft","damage":"1d8+3","damageType":"piercing"}]}'),
    ('Drow', '/icons/monsters/_mono/D.svg', 'medium', 'humanoid', '{"name":"Drow","size":"medium","type":"humanoid","ac":15,"hp":13,"speed":{"walk":30},"abilities":{"str":10,"dex":14,"con":10,"int":11,"wis":11,"cha":12},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Chain Shirt","hitDice":"3d8","skills":[{"name":"Perception","bonus":2},{"name":"Stealth","bonus":4}],"senses":["Darkvision 120 ft.","Passive Perception 12"],"languages":["Elvish","Undercommon"],"traits":[{"name":"Fey Ancestry","text":"The drow has advantage on saving throws against being charmed, and magic can''t put the drow to sleep."},{"name":"Innate Spellcasting","text":"The drow''s spellcasting ability is Charisma (spell save DC 11). It can innately cast the following spells, requiring no material components:"},{"name":"Sunlight Sensitivity","text":"While in sunlight, the drow has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Shortsword","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Hand Crossbow","text":"Ranged Weapon Attack: +4 to hit, range 30/120 ft., one target. Hit: 5 (1d6 + 2) piercing damage, and the target must succeed on a DC 13 Constitution saving throw or be poisoned for 1 hour. If the saving throw fails by 5 or more, the target is also unconscious while poisoned in this way. The target wakes up if it takes damage or if another creature takes an action to shake it awake.","attackBonus":4,"reach":"range 30/120 ft","damage":"1d6+2","damageType":"piercing","saveDc":13,"saveAbility":"con"}]}'),
    ('Druid', '/icons/monsters/_mono/D.svg', 'medium', 'humanoid', '{"name":"Druid","size":"medium","type":"humanoid","ac":11,"hp":27,"speed":{"walk":30},"abilities":{"str":10,"dex":12,"con":13,"int":12,"wis":15,"cha":11},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"16 With Barkskin","hitDice":"5d8 + 5","skills":[{"name":"Medicine","bonus":4},{"name":"Nature","bonus":3},{"name":"Perception","bonus":4}],"senses":["Passive Perception 14"],"languages":["Druidic plus any two languages"],"traits":[{"name":"Spellcasting","text":"The druid is a 4th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 12, +4 to hit with spell attacks). It has the following druid spells prepared:"}],"actions":[{"name":"Quarterstaff","text":"Melee Weapon Attack: +2 to hit (+4 to hit with shillelagh), reach 5 ft., one target. Hit: 3 (1d6) bludgeoning damage, 4 (1d8) bludgeoning damage if wielded with two hands, or 6 (1d8 + 2) bludgeoning damage with shillelagh.","attackBonus":2,"reach":"5 ft","damage":"1d6","damageType":"bludgeoning"}]}'),
    ('Dryad', '/icons/monsters/_mono/D.svg', 'medium', 'fey', '{"name":"Dryad","size":"medium","type":"fey","ac":11,"hp":22,"speed":{"walk":30},"abilities":{"str":10,"dex":12,"con":11,"int":14,"wis":15,"cha":18},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"16 With Barkskin","hitDice":"5d8","skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":5}],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["Elvish","Sylvan"],"traits":[{"name":"Innate Spellcasting","text":"The dryad''s innate spellcasting ability is Charisma (spell save DC 14). The dryad can innately cast the following spells, requiring no material components:"},{"name":"Magic Resistance","text":"The dryad has advantage on saving throws against spells and other magical effects."},{"name":"Speak with Beasts and Plants","text":"The dryad can communicate with beasts and plants as if they shared a language."},{"name":"Tree Stride","text":"Once on her turn, the dryad can use 10 feet of her movement to step magically into one living tree within her reach and emerge from a second living tree within 60 feet of the first tree, appearing in an unoccupied space within 5 feet of the second tree. Both trees must be Large or bigger."}],"actions":[{"name":"Club","text":"Melee Weapon Attack: +2 to hit (+6 to hit with shillelagh), reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage, or 8 (1d8 + 4) bludgeoning damage with shillelagh.","attackBonus":2,"reach":"5 ft","damage":"1d4","damageType":"bludgeoning"},{"name":"Fey Charm","text":"The dryad targets one humanoid or beast that she can see within 30 feet of her. If the target can see the dryad, it must succeed on a DC 14 Wisdom saving throw or be magically charmed. The charmed creature regards the dryad as a trusted friend to be heeded and protected. Although the target isn''t under the dryad''s control, it takes the dryad''s requests or actions in the most favorable way it can.","saveDc":14,"saveAbility":"wis"}]}'),
    ('Duergar', '/icons/monsters/_mono/D.svg', 'medium', 'humanoid', '{"name":"Duergar","size":"medium","type":"humanoid","ac":16,"hp":26,"speed":{"walk":25},"abilities":{"str":14,"dex":11,"con":14,"int":11,"wis":10,"cha":9},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Scale Mail, Shield","hitDice":"4d8 + 8","damageResistances":["Poison"],"senses":["Darkvision 120 ft.","Passive Perception 10"],"languages":["Dwarvish","Undercommon"],"traits":[{"name":"Duergar Resilience","text":"The duergar has advantage on saving throws against poison, spells, and illusions, as well as to resist being charmed or paralyzed."},{"name":"Sunlight Sensitivity","text":"While in sunlight, the duergar has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Enlarge (Recharges after a Short or Long Rest)","text":"For 1 minute, the duergar magically increases in size, along with anything it is wearing or carrying. While enlarged, the duergar is Large, doubles its damage dice on Strength-based weapon attacks (included in the attacks), and makes Strength checks and Strength saving throws with advantage. If the duergar lacks the room to become Large, it attains the maximum size possible in the space available."},{"name":"War Pick","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) piercing damage, or 11 (2d8 + 2) piercing damage while enlarged.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"piercing"},{"name":"Javelin","text":"Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 30/120 ft., one target. Hit: 5 (1d6 + 2) piercing damage, or 9 (2d6 + 2) piercing damage while enlarged.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Invisibility (Recharges after a Short or Long Rest)","text":"The duergar magically turns invisible until it attacks, casts a spell, or uses its Enlarge, or until its concentration is broken, up to 1 hour (as if concentrating on a spell). Any equipment the duergar wears or carries is invisible with it."}]}'),
    ('Dust Mephit', '/icons/monsters/_mono/D.svg', 'small', 'elemental', '{"name":"Dust Mephit","size":"small","type":"elemental","ac":12,"hp":17,"speed":{"walk":30,"fly":30},"abilities":{"str":5,"dex":14,"con":10,"int":9,"wis":11,"cha":10},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"5d6","skills":[{"name":"Perception","bonus":2},{"name":"Stealth","bonus":4}],"damageImmunities":["Poison"],"damageVulnerabilities":["Fire"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 12"],"languages":["Auran","Terran"],"traits":[{"name":"Death Burst","text":"When the mephit dies, it explodes in a burst of dust. Each creature within 5 feet of it must then succeed on a DC 10 Constitution saving throw or be blinded for 1 minute. A blinded creature can repeat the saving throw on each of its turns, ending the effect on itself on a success."},{"name":"Innate Spellcasting","text":"(1/Day). The mephit can innately cast sleep, requiring no material components. Its innate spellcasting ability is Charisma."}],"actions":[{"name":"Claws","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 4 (1d4 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"slashing"},{"name":"Blinding Breath (Recharge 6)","text":"The mephit exhales a 15- foot cone of blinding dust. Each creature in that area must succeed on a DC 10 Dexterity saving throw or be blinded for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","saveDc":10,"saveAbility":"dex"}]}'),
    ('Eagle', '/icons/monsters/_mono/E.svg', 'small', 'beast', '{"name":"Eagle","size":"small","type":"beast","ac":12,"hp":3,"speed":{"walk":10,"fly":60},"abilities":{"str":6,"dex":15,"con":10,"int":2,"wis":14,"cha":7},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d6","skills":[{"name":"Perception","bonus":4}],"senses":["Passive Perception 14"],"languages":["--"],"traits":[{"name":"Keen Sight","text":"The eagle has advantage on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Talons","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"slashing"}]}'),
    ('Earth Elemental', '/icons/monsters/_mono/E.svg', 'large', 'elemental', '{"name":"Earth Elemental","size":"large","type":"elemental","ac":17,"hp":126,"speed":{"walk":30,"burrow":30},"abilities":{"str":20,"dex":8,"con":20,"int":5,"wis":10,"cha":5},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"12d10 + 60","damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"damageVulnerabilities":["Thunder"],"conditionImmunities":["Exhaustion","Paralyzed","Petrified","Poisoned","Unconscious"],"senses":["Darkvision 60 ft.","Tremorsense 60 ft.","Passive Perception 10"],"languages":["Terran"],"traits":[{"name":"Earth Glide","text":"The elemental can burrow through nonmagical, unworked earth and stone. While doing so, the elemental doesn''t disturb the material it moves through."},{"name":"Siege Monster","text":"The elemental deals double damage to objects and structures."}],"actions":[{"name":"Multiattack","text":"The elemental makes two slam attacks."},{"name":"Slam","text":"Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 14 (2d8 + 5) bludgeoning damage.","attackBonus":8,"reach":"10 ft","damage":"2d8+5","damageType":"bludgeoning"}]}'),
    ('Efreeti', '/icons/monsters/_mono/E.svg', 'large', 'elemental', '{"name":"Efreeti","size":"large","type":"elemental","ac":17,"hp":200,"speed":{"walk":40,"fly":60},"abilities":{"str":22,"dex":12,"con":24,"int":16,"wis":15,"cha":16},"cr":"11","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"16d10 + 112","saves":{"int":7,"wis":6,"cha":7},"damageImmunities":["Fire"],"senses":["Darkvision 120 ft.","Passive Perception 12"],"languages":["Ignan"],"traits":[{"name":"Elemental Demise","text":"If the efreeti dies, its body disintegrates in a flash of fire and puff of smoke, leaving behind only equipment the efreeti was wearing or carrying."},{"name":"Innate Spellcasting","text":"The efreeti''s innate spellcasting ability is Charisma (spell save DC 15, +7 to hit with spell attacks). It can innately cast the following spells, requiring no material components:"}],"actions":[{"name":"Multiattack","text":"The efreeti makes two scimitar attacks or uses its Hurl Flame twice."},{"name":"Scimitar","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 13 (2d6 + 6) slashing damage plus 7 (2d6) fire damage.","attackBonus":10,"reach":"5 ft","damage":"2d6+6","damageType":"slashing"},{"name":"Hurl Flame","text":"Ranged Spell Attack: +7 to hit, range 120 ft., one target. Hit: 17 (5d6) fire damage.","attackBonus":7,"damage":"5d6","damageType":"fire"}]}'),
    ('Elephant', '/icons/monsters/_mono/E.svg', 'huge', 'beast', '{"name":"Elephant","size":"huge","type":"beast","ac":12,"hp":76,"speed":{"walk":40},"abilities":{"str":22,"dex":9,"con":17,"int":3,"wis":11,"cha":6},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"8d12 + 24","senses":["Passive Perception 10"],"languages":["--"],"traits":[{"name":"Trampling Charge","text":"If the elephant moves at least 20 feet straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a DC 12 Strength saving throw or be knocked prone. If the target is prone, the elephant can make one stomp attack against it as a bonus action."}],"actions":[{"name":"Gore","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 19 (3d8 + 6) piercing damage.","attackBonus":8,"reach":"5 ft","damage":"3d8+6","damageType":"piercing"},{"name":"Stomp","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one prone creature. Hit: 22 (3d10 + 6) bludgeoning damage.","attackBonus":8,"reach":"5 ft","damage":"3d10+6","damageType":"bludgeoning"}]}'),
    ('Elk', '/icons/monsters/_mono/E.svg', 'large', 'beast', '{"name":"Elk","size":"large","type":"beast","ac":10,"hp":13,"speed":{"walk":50},"abilities":{"str":16,"dex":10,"con":12,"int":2,"wis":10,"cha":6},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d10 + 2","senses":["Passive Perception 10"],"languages":["--"],"traits":[{"name":"Charge","text":"If the elk moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 (2d6) damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone."}],"actions":[{"name":"Ram","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) bludgeoning damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"bludgeoning"},{"name":"Hooves","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one prone creature. Hit: 8 (2d4 + 3) bludgeoning damage.","attackBonus":5,"reach":"5 ft","damage":"2d4+3","damageType":"bludgeoning"}]}'),
    ('Erinyes', '/icons/monsters/_mono/E.svg', 'medium', 'fiend', '{"name":"Erinyes","size":"medium","type":"fiend","ac":18,"hp":153,"speed":{"walk":30,"fly":60},"abilities":{"str":18,"dex":16,"con":18,"int":14,"wis":14,"cha":18},"cr":"12","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Plate","hitDice":"18d8 + 72","saves":{"dex":7,"con":8,"wis":6,"cha":8},"damageResistances":["Cold","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Truesight 120 ft.","Passive Perception 12"],"languages":["Infernal","Telepathy 120 ft."],"traits":[{"name":"Hellish Weapons","text":"The erinyes''s weapon attacks are magical and deal an extra 13 (3d8) poison damage on a hit (included in the attacks)."},{"name":"Magic Resistance","text":"The erinyes has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The erinyes makes three attacks."},{"name":"Longsword","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 8 (1d8 + 4) slashing damage, or 9 (1d10 + 4) slashing damage if used with two hands, plus 13 (3d8) poison damage.","attackBonus":8,"reach":"5 ft","damage":"1d8+4","damageType":"slashing"},{"name":"Longbow","text":"Ranged Weapon Attack: +7 to hit, range 150/600 ft., one target. Hit: 7 (1d8 + 3) piercing damage plus 13 (3d8) poison damage, and the target must succeed on a DC 14 Constitution saving throw or be poisoned. The poison lasts until it is removed by the lesser restoration spell or similar magic.","attackBonus":7,"reach":"range 150/600 ft","damage":"1d8+3","damageType":"piercing","saveDc":14,"saveAbility":"con"}],"reactions":[{"name":"Parry","text":"The erinyes adds 4 to its AC against one melee attack that would hit it. To do so, the erinyes must see the attacker and be wielding a melee weapon."}]}'),
    ('Ettercap', '/icons/monsters/_mono/E.svg', 'medium', 'monstrosity', '{"name":"Ettercap","size":"medium","type":"monstrosity","ac":13,"hp":44,"speed":{"walk":30,"climb":30},"abilities":{"str":14,"dex":15,"con":13,"int":7,"wis":12,"cha":8},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"8d8 + 8","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":4},{"name":"Survival","bonus":3}],"senses":["Darkvision 60 ft.","Passive Perception 13"],"languages":["--"],"traits":[{"name":"Spider Climb","text":"The ettercap can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Web Sense","text":"While in contact with a web, the ettercap knows the exact location of any other creature in contact with the same web."},{"name":"Web Walker","text":"The ettercap ignores movement restrictions caused by webbing."}],"actions":[{"name":"Multiattack","text":"The ettercap makes two attacks: one with its bite and one with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 6 (1d8 + 2) piercing damage plus 4 (1d8) poison damage. The target must succeed on a DC 11 Constitution saving throw or be poisoned for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"piercing","saveDc":11,"saveAbility":"con"},{"name":"Claws","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"2d4+2","damageType":"slashing"},{"name":"Web (Recharge 5–6)","text":"Ranged Weapon Attack: +4 to hit, range 30/60 ft., one Large or smaller creature. Hit: The creature is restrained by webbing. As an action, the restrained creature can make a DC 11 Strength check, escaping from the webbing on a success. The effect also ends if the webbing is destroyed. The webbing has AC 10, 5 hit points, vulnerability to fire damage, and immunity to bludgeoning, poison, and psychic damage.","attackBonus":4,"reach":"range 30/60 ft"}]}'),
    ('Ettin', '/icons/monsters/_mono/E.svg', 'large', 'giant', '{"name":"Ettin","size":"large","type":"giant","ac":12,"hp":85,"speed":{"walk":40},"abilities":{"str":21,"dex":8,"con":17,"int":6,"wis":10,"cha":8},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"10d10 + 30","skills":[{"name":"Perception","bonus":4}],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["Giant","Orc"],"traits":[{"name":"Two Heads","text":"The ettin has advantage on Wisdom (Perception) checks and on saving throws against being blinded, charmed, deafened, frightened, stunned, and knocked unconscious."},{"name":"Wakeful","text":"When one of the ettin''s heads is asleep, its other head is awake."}],"actions":[{"name":"Multiattack","text":"The ettin makes two attacks: one with its battleaxe and one with its morningstar."},{"name":"Battleaxe","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 14 (2d8 + 5) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+5","damageType":"slashing"},{"name":"Morningstar","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 14 (2d8 + 5) piercing damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+5","damageType":"piercing"}]}'),
    ('Fire Elemental', '/icons/monsters/_mono/F.svg', 'large', 'elemental', '{"name":"Fire Elemental","size":"large","type":"elemental","ac":13,"hp":102,"speed":{"walk":50},"abilities":{"str":10,"dex":17,"con":16,"int":6,"wis":10,"cha":7},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"12d10 + 36","damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Exhaustion","Grappled","Paralyzed","Petrified","Poisoned","Prone","Restrained","Unconscious"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Ignan"],"traits":[{"name":"Fire Form","text":"The elemental can move through a space as narrow as 1 inch wide without squeezing. A creature that touches the elemental or hits it with a melee attack while within 5 feet of it takes 5 (1d10) fire damage. In addition, the elemental can enter a hostile creature''s space and stop there. The first time it enters a creature''s space on a turn, that creature takes 5 (1d10) fire damage and catches fire; until someone takes an action to douse the fire, the creature takes 5 (1d10) fire damage at the start of each of its turns."},{"name":"Illumination","text":"The elemental sheds bright light in a 30-foot radius and dim light in an additional 30 feet."},{"name":"Water Susceptibility","text":"For every 5 feet the elemental moves in water, or for every gallon of water splashed on it, it takes 1 cold damage."}],"actions":[{"name":"Multiattack","text":"The elemental makes two touch attacks."},{"name":"Touch","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) fire damage. If the target is a creature or a flammable object, it ignites. Until a creature takes an action to douse the fire, the target takes 5 (1d10) fire damage at the start of each of its turns.","attackBonus":6,"reach":"5 ft","damage":"2d6+3","damageType":"fire"}]}'),
    ('Fire Giant', '/icons/monsters/_mono/F.svg', 'huge', 'giant', '{"name":"Fire Giant","size":"huge","type":"giant","ac":18,"hp":162,"speed":{"walk":30},"abilities":{"str":25,"dex":9,"con":23,"int":10,"wis":14,"cha":13},"cr":"9","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Plate","hitDice":"13d12 + 78","saves":{"dex":3,"con":10,"cha":5},"skills":[{"name":"Athletics","bonus":11},{"name":"Perception","bonus":6}],"damageImmunities":["Fire"],"senses":["Passive Perception 16"],"languages":["Giant"],"actions":[{"name":"Multiattack","text":"The giant makes two greatsword attacks."},{"name":"Greatsword","text":"Melee Weapon Attack: +11 to hit, reach 10 ft., one target. Hit: 28 (6d6 + 7) slashing damage.","attackBonus":11,"reach":"10 ft","damage":"6d6+7","damageType":"slashing"},{"name":"Rock","text":"Ranged Weapon Attack: +11 to hit, range 60/240 ft., one target. Hit: 29 (4d10 + 7) bludgeoning damage.","attackBonus":11,"reach":"range 60/240 ft","damage":"4d10+7","damageType":"bludgeoning"}]}'),
    ('Flameskull', '/icons/monsters/_mono/F.svg', 'tiny', 'undead', '{"name":"Flameskull","size":"tiny","type":"undead","ac":13,"hp":40,"speed":{"walk":0,"fly":40,"hover":true},"abilities":{"str":1,"dex":17,"con":14,"int":16,"wis":10,"cha":11},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"9d4 + 18","skills":[{"name":"Arcana","bonus":5},{"name":"Perception","bonus":2}],"damageResistances":["Lightning","Necrotic","Piercing"],"damageImmunities":["Cold","Fire","Poison"],"conditionImmunities":["Charmed","Frightened","Paralyzed","Poisoned","Prone"],"senses":["Darkvision 60 ft.","Passive Perception 12"],"languages":["Common"],"traits":[{"name":"Illumination","text":"The flameskull sheds either dim light in a 15-foot radius, or bright light in a 15-foot radius and dim light for an additional 15 feet. It can switch between the options as an action."},{"name":"Magic Resistance","text":"The flameskull has advantage on saving throws against spells and other magical effects."},{"name":"Rejuvenation","text":"If the flameskull is destroyed, it regains all its hit points in 1 hour unless holy water is sprinkled on its remains or a dispel magic or remove curse spell is cast on them."},{"name":"Spellcasting","text":"The flameskull is a 5th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 13, +5 to hit with spell attacks). It requires no somatic or material components to cast its spells. The flameskull has the following wizard spells prepared:"}],"actions":[{"name":"Multiattack","text":"The flameskull uses Fire Ray twice."},{"name":"Fire Ray","text":"Ranged Spell Attack: +5 to hit, range 30 ft., one target. Hit: 10 (3d6) fire damage.","attackBonus":5,"damage":"3d6","damageType":"fire"}]}'),
    ('Flesh Golem', '/icons/monsters/_mono/F.svg', 'medium', 'construct', '{"name":"Flesh Golem","size":"medium","type":"construct","ac":9,"hp":93,"speed":{"walk":30},"abilities":{"str":19,"dex":9,"con":18,"int":6,"wis":10,"cha":5},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"11d8 + 44","damageImmunities":["Lightning","Poison","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Adamantine"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Paralyzed","Petrified","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Understands the languages of its creator but can''t speak"],"traits":[{"name":"Berserk","text":"Whenever the golem starts its turn with 40 hit points or fewer, roll a d6. On a 6, the golem goes berserk. On each of its turns while berserk, the golem attacks the nearest creature it can see. If no creature is near enough to move to and attack, the golem attacks an object, with preference for an object smaller than itself. Once the golem goes berserk, it continues to do so until it is destroyed or regains all its hit points."},{"name":"Aversion of Fire","text":"If the golem takes fire damage, it has disadvantage on attack rolls and ability checks until the end of its next turn."},{"name":"Immutable Form","text":"The golem is immune to any spell or effect that would alter its form."},{"name":"Lightning Absorption","text":"Whenever the golem is subjected to lightning damage, it takes no damage and instead regains a number of hit points equal to the lightning damage dealt."},{"name":"Magic Resistance","text":"The golem has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","text":"The golem''s weapon attacks are magical."}],"actions":[{"name":"Multiattack","text":"The golem makes two slam attacks."},{"name":"Slam","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+4","damageType":"bludgeoning"}]}'),
    ('Flying Snake', '/icons/monsters/_mono/F.svg', 'tiny', 'beast', '{"name":"Flying Snake","size":"tiny","type":"beast","ac":14,"hp":5,"speed":{"walk":30,"fly":60,"swim":30},"abilities":{"str":4,"dex":18,"con":11,"int":2,"wis":12,"cha":5},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d4","senses":["Blindsight 10 ft.","Passive Perception 11"],"languages":["--"],"traits":[{"name":"Flyby","text":"The snake doesn''t provoke opportunity attacks when it flies out of an enemy''s reach."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 1 piercing damage plus 7 (3d4) poison damage.","attackBonus":6,"reach":"5 ft","damage":"3d4","damageType":"poison"}]}')
  ) as v(name, image_url, size, ctype, mb)
